INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (97,'安昂传奇：最后的气宗',1,'ac13.jpg','2026','劳伦·蒙哥马利','에릭 남 / 戴夫·巴蒂斯塔 / 杰西卡·马滕','派拉蒙和尼克宣布“降世神通”系列开发三部新的电影，仍是动画形式。第一部由《降世神通：最后的气宗》导演Lauren Montgomery执导，《最后的气宗》主创Bryan Konietzko和Michael DiMartino担任制片人。',9,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (98,'鬼灭之刃：无限城篇 第一章 猗窝座再袭',1,'ac14.jpg','2025','外崎春雄','花江夏树 / 樱井孝宏 / 石田彰','当鬼杀队的成员和柱之人在为即将到来的与鬼的战斗做准备，完成共同的体能训练——柱之训练时，鬼舞辻无惨在产屋敷宅邸出现。由于鬼杀队的主公处于危险之中，炭治郎和柱急忙赶往总部，但却被鸣女推入一个神秘的异空间。炭治郎和鬼杀队的目标是鬼的堡垒——无…',9,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (99,'夜巡毒枭',1,'ac15.jpg','2026','Chava Cartas','Alfonso Herrera / 诺伊·埃尔南德斯 / Héctor Kotsifakis','两位墨西哥员警不幸得罪一名残忍的毒枭后，必须拼命撑过值勤的最后几小时。改编自真实事件。',9,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (100,'电锯人剧场版：蕾塞篇',1,'ac16.jpg','2025','吉原达矢','户谷菊之介 / 井泽诗织 / 楠木灯','故事延续TV动画的最终章，讲述男主角电次在偶然邂逅的神秘少女蕾塞的庇护下，在快节奏的战斗中，奔向难以预测的命运。  电次，一个少年，与“电锯恶魔”签订契约，化身“电锯人”，成为隶属于公安部魔物对策特别课四课的魔物猎人，与魔物战斗。正兴奋地…',9,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (101,'蝙蝠侠：黑暗骑士',1,'ac17.jpg','2008','克里斯托弗·诺兰','克里斯蒂安·贝尔 / 希斯·莱杰 / 艾伦·艾克哈特','蝙蝠侠在吉姆·戈登警官和检察官哈维·登特的协助下，致力于彻底铲除哥谭市的犯罪组织。然而，三人的合作很快遭到犯罪天才小丑的破坏。小丑将哥谭市拖入混乱，迫使蝙蝠侠游走于英雄与私刑者的界限之间。',9,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (102,'指环王3：王者无敌',1,'ac18.jpg','2003','彼得·杰克逊','伊利亚·伍德 / 伊恩·麦克莱恩 / 维果·莫特森','索伦大军为剿灭人类种族，已对刚铎都城米那斯提力斯展开围攻。这座昔日的伟大王国由一位日渐衰弱的摄政王守护，此刻比任何时候都更需要它的王者归来。但阿拉贡能否回应血脉的召唤，成为命定之君？中土世界的命运，正系于他宽阔的双肩。',9,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (103,'蜘蛛侠：崭新之日',1,'ac19.jpg','2026','德斯汀·丹尼尔·克雷顿','汤姆·赫兰德 / 萨迪·辛克 / 特拉梅尔·提尔曼','彼得·帕克以蜘蛛侠的身份全职打击犯罪，却发现自己的身体发生了无法控制的变化。与此同时，一股神秘而强大的新威胁正向他和所爱之人逼近。',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (104,'切腹',1,'ac20.jpg','1962','小林正树','仲代达矢 / 石滨朗 / 岩下志麻','家族没落后，失业武士仲代达矢来到井伊藩主的宅邸，请求允许他在此切腹自尽。藩主家臣认定这名走投无路的浪人只是想讨份差事，遂逼迫他当场切腹——却低估了他坚守的信念与对尊严的执着。本片由小林正树执导，荣获戛纳电影节评委会特别奖，以凌厉笔触刻画了…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (105,'七武士',1,'ac21.jpg','1954','黑泽明','三船敏郎 / 志村乔 / 稻叶义男','这部影史最具震撼力的史诗巨制，讲述十六世纪某村庄的绝望村民雇佣七位武士抵御山贼侵袭的故事。黑泽明历时三个多小时的银幕征程，通过传奇演员三船敏郎与志村乔的演绎，将哲学沉思与娱乐观赏、细腻人情与激烈战斗完美交融，铸就这部关于勇气与希望的丰碑之…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (106,'指环王1：护戒使者',1,'ac22.jpg','2001','彼得·杰克逊','伊利亚·伍德 / 伊恩·麦克莱恩 / 维果·莫特森','J.R.R.托尔金的文学巨著首次以电影形式磅礴呈现——这是一场正义对抗邪恶的史诗冒险，一段关于友谊力量与个人勇气的传奇，更是一次为人类纪元开辟道路的英雄征程。',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (107,'指环王2：双塔奇兵',1,'ac23.jpg','2002','彼得·杰克逊','伊利亚·伍德 / 伊恩·麦克莱恩 / 维果·莫特森','在J.R.R.托尔金史诗三部曲的第二篇章中，护戒同盟队面对难以想象的敌军与诡谲阴谋，同时见证了远古奇迹与同胞未觉醒的力量。',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (108,'罗小黑战记',1,'ac24.jpg','2019','MTJJ','山新 / 刘明月 / 郝祥海','在熙攘的人类世界里，许多妖精隐匿其中，与人类相安无事地生活着。猫妖罗小黑因为家园遭到破坏，被迫开始流浪。在旅途中，他先后遇到妖精同类与人类伙伴，并逐渐卷入人类与妖精之间的纷争。面对截然不同的立场与选择，小黑也开始寻找真正属于自己的归宿……',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (109,'保护者',1,'ac25.jpg','2026','阿德里安·格鲁伯格','米拉·乔沃维奇 / 马修·莫迪恩 / 伊莎贝尔·迈尔斯','退役军人尼基与女儿克洛伊平静生活，却在废弃工厂醒来后发现女儿遭绑架，她必须重返黑暗世界，对抗人贩子、警察与军方，在72小时黄金救援期内救回女儿。',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (110,'星球大战5：帝国反击战',1,'ac26.jpg','1980','厄文·克什纳','马克·哈米尔 / 哈里森·福特 / 凯丽·费雪','星球大战事件三年后，帝国军队继续追捕义军。义军在霍斯冰原星球战败后，卢克前往达戈巴星球，跟随自共和国覆灭后隐居的绝地大师尤达进行训练。为诱使卢克堕入黑暗面，达斯·维达将年轻的天行者引入贝斯平云城的陷阱。在与西斯尊主的激烈光剑对决中，卢克面…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (111,'蜘蛛侠：纵横宇宙',1,'ac27.jpg','2023','贾斯汀·K·汤普森 / 肯普·鲍尔斯 / 乔伊姆·多斯·桑托斯','沙梅克·摩尔 / 海莉·斯坦菲尔德 / 布莱恩·泰里·亨利','成为蜘蛛侠后的迈尔斯·莫拉莱斯一边守护自己的城市，一边努力在英雄身份与家庭生活之间寻找平衡，却始终怀念曾与自己并肩作战的格温和其他伙伴。一次意外重逢后，迈尔斯跟随蜘蛛格温穿越平行宇宙，第一次来到由来自不同世界的蜘蛛侠组成的“蜘蛛联盟”。然…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (112,'捕风追影',1,'ac28.jpg','2025','杨子','成龙 / 张子枫 / 梁家辉','一伙天才盗匪劫走数亿资产，却凭借超强反侦察能力全身而退，戏耍警方“天眼”系统。一筹莫展之际，澳门司警局请回了隐退多年的跟踪专家黄德忠，他培养年轻司警何秋果等人，重组“神秘跟踪队”，最终锁定了盗匪团的幕后狼王傅隆生。当警方布下天罗地网之时，…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (113,'护肝人',1,'ac29.jpg','2026','斯科特·沃','艾伦·瑞奇森 / 欧文·威尔逊 / 罗德里戈·桑托罗','高端特种押运员汉克·马龙必须在三小时内，将一颗肝脏从洛杉矶国际机场运往圣巴巴拉的一家医院，用于一台紧急移植手术。受赠者是一名濒危的七岁女孩，她拥有全球极为罕见的血型。偏偏南加州最危险犯罪集团的头目，也急需这颗器官。',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (114,'这个杀手不太冷',1,'ac30.jpg','1994','吕克·贝松','让·雷诺 / 娜塔莉·波特曼 / 加里·奥德曼','里昂是名孤独的职业杀手，受人雇佣。一天，邻居家小姑娘马蒂尔达敲开他的房门，要求在他那里暂避杀身之祸。原来邻居家的主人是警方缉毒组的眼线，只因贪污了一小包毒品而遭恶警杀害全家的惩罚。马蒂尔达得到里昂的留救，幸免于难，并留在里昂那里。里昂教小…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (115,'边境奇袭',1,'ac31.jpg','2025','Chava Cartas','路易斯·阿伯提 / 诺伊·埃尔南德斯 / Leonardo Alonso','一场人质营救行动带来了新的敌人，格雷罗上尉和他的精英士兵们必须应对残忍犯罪团伙的埋伏。',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (116,'新世纪福音战士剧场版：Air／真心为你',1,'ac32.jpg','1997','庵野秀明 / 鹤卷和哉','绪方惠美 / 林原惠美 / 三石琴乃','《新世纪福音战士》系列第二部剧场版，于 1997 年 7 月 19 日在日本上映。全名：《新世纪福音战士剧场版：THE END OF EVANGELION》（日语：新世紀エヴァンゲリオン 劇場版 THE END OF EVANGELION…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (117,'惩罚者：最后一击',1,'ac33.jpg','2026','雷纳尔多·马库斯·格林','乔·博恩瑟 / 黛博拉·安·沃尔 / Jason R. Moore','失去家人多年后，弗兰克·卡塞尔依然被过去的创伤与幻象困扰，试图远离曾经作为“惩罚者”的暴力人生。然而，犯罪家族首领努奇为了替死去的亲人复仇，对弗兰克发出悬赏，引来大批罪犯追杀。随着暴力逐渐波及身边的无辜者，原本想要逃离过去的弗兰克不得不再…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (118,'复仇者联盟4：终局之战',1,'ac34.jpg','2019','安东尼·罗素 / 乔·罗素','小罗伯特·唐尼 / 克里斯·埃文斯 / 马克·鲁法洛','灭霸集齐六颗无限宝石后的一声响指，让宇宙中半数生命灰飞烟灭。幸存的复仇者们几近绝望，即使找到灭霸，也发现无限宝石已经被毁，希望似乎彻底破灭。五年后，迷失在量子领域的蚁人意外回到现实世界，并带来了一个可能逆转一切的办法。托尼·斯塔克、美国队…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (119,'复仇者联盟3：无限战争',1,'ac35.jpg','2018','安东尼·罗素 / 乔·罗素','小罗伯特·唐尼 / 克里斯·埃文斯 / 克里斯·海姆斯沃斯','来自宇宙深处的强大敌人灭霸开始寻找六颗无限宝石，企图利用它们的力量实现自己的计划。随着他的军团向地球和宇宙各处发动袭击，复仇者联盟、银河护卫队以及众多超级英雄被迫卷入这场前所未有的战争。此时的复仇者们仍因过去的分裂而各自行动，却不得不在不…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (120,'鬼灭之刃：无限列车篇',1,'ac36.jpg','2020','外崎春雄','花江夏树 / 鬼头明里 / 下野纮','炭治郎等人完成蝴蝶屋的训练，下一个目的地是开往黑暗的无限列车。以多人行踪不明的这辆列车为舞台，炭治郎带着祢豆子与善逸、伊之助一行人，与鬼杀队最强剑士〝柱〞其中之一炎柱炼狱杏寿郎会合，新的任务即将开始！',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (121,'角斗士',1,'ac37.jpg','2000','雷德利·斯科特','罗素·克劳 / 华金·菲尼克斯 / 康妮·尼尔森','马克西蒙斯是罗马帝国战功显赫，受人拥戴的大将军。老国王马库斯·奥利利乌斯对大将军赏识有加，有意加冕于他。老国王对将军这种超越亲情的宠爱自然招来太子康莫迪乌斯的妒忌与不安，太子伺机杀害父亲，抢先登上王位，并马上下令诛杀大将军一家。马克西蒙斯…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (122,'火遮眼',1,'ac38.jpg','2026','谷垣健治','谢苗 / 乔·塔斯利姆 / 杨恩又','东南亚某地，失语的维修工王伟与女儿雨晴相依为命。一天，雨晴在街头被一个人口贩卖组织掳走，王伟向警方求助，却发现当地执法系统充斥着腐败与冷漠。走投无路之下，他只能凭自己的力量追查女儿下落，并在过程中结识记者纳文。纳文的妻子曾因调查同一犯罪网…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (123,'福音战士新剧场版：终',1,'ac39.jpg','2021','中山胜一 / 鹤卷和哉 / 前田真宏 / 庵野秀明','绪方惠美 / 宫村优子 / 坂本真绫','反NERV组织WILLE的成员在红化的巴黎旧城区执行作战任务。与此同时，碇真嗣、明日香与绫波零在日本的大地上徘徊，故事迎来最终结局。',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (124,'星球大战4：新希望',1,'ac40.jpg','1977','乔治·卢卡斯','马克·哈米尔 / 哈里森·福特 / 凯丽·费雪','很久以前，在一个遥远的银河系……莱娅公主被邪恶的帝国势力挟为人质，企图镇压反抗银河帝国的起义军。卢克·天行者与汉·索罗船长携手可爱的机器人搭档R2-D2和C-3PO，共同踏上拯救美丽公主、恢复银河系正义的征程。[20世纪福克斯]',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (125,'哪吒之魔童闹海',1,'ac41.jpg','2025','饺子','吕艳婷 / 囧森瑟夫 / 瀚墨','天劫之后，哪吒和敖丙的灵魂虽然得以保全，却因失去肉身而面临魂飞魄散的危险。为了救下二人，太乙真人决定借助七色宝莲为他们重塑肉身。然而重塑的过程并不顺利，一场新的危机也随之而来。经历天劫后本应迎来新生的哪吒与敖丙，再次站在命运的十字路口，他…',8,0);
