INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (127,'终结者2：审判日',1,'ac43.jpg','1991','詹姆斯·卡梅隆','阿诺德·施瓦辛格 / 琳达·汉密尔顿 / 爱德华·弗朗','上一部中，超级电脑“天网”阻止人类抵抗领袖约翰·康纳诞生的行动失败，时隔13年后，在“审判日”到来之前，“天网”派出了更加先进的生化机器人T-1000（罗伯特·帕特里克 饰）从公元2029年回到洛杉矶追杀已经长大的约翰，与此同时，约翰也派…',8,0);
