INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (130,'我的英雄学院：英雄崛起',1,'ac46.jpg','2019','长崎健司','山下大辉 / 冈本信彦 / 井上芳雄','新剧场版由原著作者堀越耕平担任总监修/角色原案，将展开原创故事。堀越耕平表示该剧场版在某种意义上是原作的最终回。',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (131,'群体',1,'ac47.jpg','2026','延尚昊','全智贤 / 具教焕 / 池昌旭','因不明感染事件被封锁在一栋大楼内的幸存者们，与以不可预测形态进化的感染者展开殊死搏斗。随着感染不断扩散，幸存者被迫在有限空间中寻找生路，同时面对越来越聪明、越来越危险的感染者。全智贤在片中饰演生命工程学教授兼幸存者领袖权世贞。她不仅要带领…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (132,'杀死比尔：血色全传',1,'ac48.jpg','2011','昆汀·塔伦蒂诺','乌玛·瑟曼 / 刘玉玲 / 薇薇卡·福克斯','昆汀·塔伦蒂诺的本片将第一卷与第二卷合二为一，呈现出一部未分级的完整史诗一一完全以导演原本意图呈现，并包含一段前所未见的新动画片段。新娘（乌玛·瑟曼 Uma Thurman 饰）曾是暗杀组织中的一名成员，也是组织首脑比尔（大卫·卡拉丁 D…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (133,'咒术回战0',1,'ac49.jpg','2021','朴性厚','绪方惠美 / 花泽香菜 / 中村悠一','乙骨忧太是一个高中生，他正面临着一个严重的问题，青梅竹马理香变成了一个咒灵，不会让他一个人呆着。由于理香不是普通的咒灵，他的困境被咒术高专的老师五条悟注意到了。五条说服忧太入学，但他赶得及吗？',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (134,'真人快打传奇：蝎子的复仇',1,'ac50.jpg','2020','Ethan Spaulding','詹妮弗·卡朋特 / 乔尔·麦克哈尔 / Jordan Rodrigues','聚焦了异世界和地球之间的千载难逢的比赛，这场比赛将最终决定地球和人类所有的公民的命运。地球保护者雷电必须聚集其领域最伟大的战士，以从邪恶的尚宗手上保卫地球，从而结束所有战斗。',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (135,'挽救计划',2,'kh13.jpg','2026','菲尔·洛德 / 克里斯托弗·米勒','瑞恩·高斯林 / 桑德拉·惠勒 / 詹姆斯·奥尔蒂斯','太阳正在被“吃”掉，绝望吞噬地球。一名“平凡”的中学教师格雷斯（瑞恩·高斯林 饰）背负全人类的希望，踏上“太空不归路”。末路孤旅中，他意外遇到一位外星萌友，一个同样身陷绝境的外星工程师，这对“宇宙搭子”成了两个文明最后的救命稻草。他们能否…',9,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (136,'回到未来',2,'kh14.jpg','1985','罗伯特·泽米吉斯','迈克尔·J·福克斯 / 克里斯托弗·劳埃德 / 克里斯平·格洛弗','马蒂·麦克弗莱，一位典型的八十年代美国青少年，意外被一台由钚动力驱动的德罗宁“时间机器”送回到1955年——这台机器由一位略带疯狂的科学家发明。在这段时常癫狂、总是惊人的穿越之旅中，马蒂必须确保他那正值青春期的未来父母相遇并坠入爱河，他才…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (137,'荒野机器人',2,'kh15.jpg','2024','克里斯·桑德斯','露皮塔·尼永奥 / 佩德罗·帕斯卡 / 基特·康纳','梦工厂动画全新改编文学畅销作品——彼得·布朗荣获大奖、备受喜爱的《纽约时报》榜首畅销书《荒野机器人》。这段史诗冒险讲述机器人“ROZZUM单元7134”（简称“罗兹”）的旅程：她因船只失事流落荒岛，必须学会适应严酷环境，逐渐与岛上动物建立…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (138,'神秘博士：博士之日',2,'kh16.jpg','2013','Nick Hurran','马特·史密斯 / 大卫·田纳特 / 约翰·赫特','被列入世界吉尼斯纪录的最长科幻系列电视剧《神秘博士》将迎来第50周年的播放纪念。为了庆祝这部长寿电视剧的半百生日，英国广播公司BBC电视台制作了《神秘博士》特辑，不仅将在英国电视台和电影院同步播映，还将首次以3D形式与观众见面。  　　INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (139,'异形',2,'kh17.jpg','1979','雷德利·斯科特','汤姆·斯凯里特 / 西格妮·韦弗 / 维罗尼卡·卡维特','未来的世界，人类已能轻松穿梭于星际之间，在太空中展开商业活动。“诺斯特罗莫”是在太空活动的众多星际商业运输船之一。一次，它完成任务满载太空矿石返航地球时，突然收到了一组奇怪的信号，由于这可能是求救信号，飞船接到指令前往信号源地进行搜救。经…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (140,'发条橙',2,'kh18.jpg','1971','斯坦利·库布里克','马尔科姆·麦克道威尔 / 帕特里克·马吉 / 卡罗尔·杜瑞','阿利斯是一位无恶不作的少年，他的特殊喜好是边听贝多芬的交响曲边奸淫女性，某次他进入一所别墅抢劫一番后，打残了该别墅的主人——一名小说家，并用特殊喜好蹂躏了其妻子。后来因为杀了一名单身女子，阿利斯入狱并接受了特殊的人格治疗，出狱后，他对淫乐…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (141,'沙丘2',2,'kh19.jpg','2024','丹尼斯·维伦纽瓦','提莫西·查拉梅 / 赞达亚·科尔曼 / 丽贝卡·弗格森','《沙丘2》承接第一部剧情，讲述保罗·厄崔迪（提莫西·查拉梅 Timothée Chalamet 饰）被帕迪沙皇帝和哈克南人联手灭族后，在厄拉科斯星球遇到弗雷曼女战士契妮（赞达亚 Zendaya 饰）以及加入弗雷曼人后展开的传奇旅程。保罗与…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (142,'河狸变身计划',2,'kh20.jpg','2026','丹尼尔·钟','派珀·柯达 / 鲍比·莫伊尼汉 / 乔恩·哈姆','梅宝是一位对动物世界充满好奇的年轻女孩，她利用先进的意识上传技术，将自己的思维注入一只机械河狸体内。以这种独特的形态，梅宝结识了河狸王国的乔治国王等动物伙伴。然而，一个由房地产开发计划带来的威胁，正试图破坏动物们的栖息地。梅宝与她的新朋友…',8,0);
