INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (144,'暖暖内含光',2,'kh22.jpg','2004','米歇尔·贡德里','金·凯瑞 / 凯特·温斯莱特 / 克斯汀·邓斯特','内向沉稳的约尔•巴瑞斯（金•凯瑞 饰）在一次聚会中认识了率真随性的克莱门汀•克罗斯基（凯特•温丝莱特 饰），二人成为情侣。和普通的情侣一样，他们的日子也在甜蜜和争吵中度过。2004年情人节前夕，当约尔精心准备好礼物，为不久前一次争吵找到克…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (145,'大都会',2,'kh23.jpg','1927','弗里茨·朗','Gustav Fröhlich / Brigitte Helm / Alfred Abel','这部1927年的鸿篇巨制或许堪称默片时代的巅峰成就，弗里茨·朗将二十年代通俗小说狂热的叙事节奏，与自身对人性幽暗面的深刻洞察熔铸一体。',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (146,'复仇者联盟',2,'kh24.jpg','2012','乔斯·韦登','小罗伯特·唐尼 / 克里斯·埃文斯 / 马克·鲁法洛','当洛基带着来自宇宙的威胁降临地球，并夺走拥有强大力量的宇宙魔方，一场前所未有的危机随之爆发。面对任何单一英雄都难以应对的敌人，神盾局局长尼克·弗瑞启动“复仇者计划”，试图将钢铁侠、美国队长、雷神、绿巨人、黑寡妇和鹰眼召集到一起。然而，这群…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (147,'潜行者',2,'kh25.jpg','1979','安德烈·塔可夫斯基','阿丽莎·弗莱因德利希 / 亚历山大·凯丹诺夫斯基 / 阿纳托利·索洛尼琴','安德烈·塔可夫斯基在苏联时期的最后一部作品，是一次穿越神秘后末日景观的形而上学旅程，亦是一场独一无二的精妙观影体验。受雇的向导——“潜行者”——带领一位作家和一位教授深入“区”的核心地带，这个长期封闭的灾难禁区中，三人最终逼近了传说中的“…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (148,'怪形',2,'kh26.jpg','1982','约翰·卡朋特','库尔特·拉塞尔 / 威尔福德·布里姆利 / T·K·卡特','1982年冬天，挪威科考队的一架直升机突然打破了南极大陆的平静，直升机疯狂的追逐一只雪橇犬，最后坠毁在美国科考营地的附近。美国科考队员对挪威考察队近期人员骤减的情况有所耳闻，于是飞行员麦克（Kurt Russell 饰）与众人赶赴挪威营地…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (149,'2001太空漫游',2,'kh27.jpg','1968','斯坦利·库布里克','凯尔·杜拉 / 加里·洛克伍德 / 威廉·西尔维斯特','本片是一次通向未来的倒计时，一张指引人类命运的地图，一场对无限的求索。库布里克为开启这场未来之旅，先回溯至我们史前的猿类祖先时期，随即跨越数千年（通过电影史上一次极具震撼的跳接）来到已被殖民的太空，最终将宇航员鲍曼（凯尔·杜拉 饰）送入未…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (150,'变形金刚：起源',2,'kh28.jpg','2024','乔什·库利','克里斯·海姆斯沃斯 / 布莱恩·泰里·亨利 / 斯嘉丽·约翰逊','影片将时间线拨回赛博坦时期，生活在赛博坦星球的擎天柱（克里斯·海姆斯沃斯 Chris Hemsworth 配音）与威震天（布莱恩·泰里·亨利 Brian Tyree Henry 配音）才20岁出头，是情同手足的朋友，此时他们还是没有变形能…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (151,'侏罗纪公园',2,'kh29.jpg','1993','史蒂文·斯皮尔伯格','山姆·尼尔 / 劳拉·邓恩 / 杰夫·高布伦','亿万富豪约翰·哈蒙德利用先进的遗传技术，从封存在琥珀中的远古蚊子血液里提取恐龙DNA，在努布拉岛成功复活了早已灭绝的恐龙，并建造了一座前所未有的主题公园“侏罗纪公园”。在正式开放之前，他邀请古生物学家艾伦·格兰特、艾丽·塞特勒和数学家伊恩…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (152,'龙珠超：布罗利',2,'kh30.jpg','2018','长峰达也','野泽雅子 / 久川绫 / 堀川亮','本次剧场版就如同标题《龙珠超 布罗利》所要表达的一样，是关于只在以前的剧场版动画中登场过的布罗利和悟空他们之间的故事。不仅如此，这次的电影还涉及到了动画中没有描写的弗利萨军队与赛亚人之间的历史。  因为在当时的《龙珠Z 燃起来！！热战・烈…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (153,'异形2',2,'kh31.jpg','1986','詹姆斯·卡梅隆','西格妮·韦弗 / 凯莉·赫恩 / 迈克尔·比恩','在这部承接《异形》剧情的动作续集中，西格妮·韦弗回归饰演蕾普莉——人类首次遭遇异形怪物后的唯一幸存者。她关于异形及其船员命运的陈述起初备受质疑，直到LV-426殖民星球上的居民神秘失踪，促使她加入一支奉命前往调查的高科技殖民陆战队。',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (154,'钢铁巨人',2,'kh32.jpg','1999','布拉德·伯德','詹妮弗·安妮斯顿 / 小哈里·康尼克 / 范·迪塞尔','1950年代，一个巨型金属机器坠落在缅因州，令镇民惊恐。然而，这个机器人却与名叫霍加斯的九岁男孩成为了朋友。男孩必须保护它，使其免受镇民的偏见以及一心要摧毁机器人的政府特工的威胁。',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (155,'机器人之梦',2,'kh33.jpg','2023','巴勃罗·贝尔赫','伊万·拉班达 / 阿尔伯特·特里佛·塞加拉 / 拉法·卡尔沃','20世纪80年代的曼哈顿，一只独自生活的小狗厌倦了日复一日的孤单，于是通过电视广告订购并组装了一个机器人作为伙伴。两个原本孤独的生命很快成为形影不离的朋友，一起穿梭在纽约街头，分享生活中的快乐。夏天即将结束时，它们来到海滩游玩，机器人却因…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (156,'阿基拉',2,'kh34.jpg','1988','大友克洋','岩田光央 / 佐佐木望 / 小山茉美','1988年7月，关东地区使用新型炸弹进行爆破，第三次世界大战即刻爆发。31年后，人类从一片废墟中重建都市，东京湾上建立了巨大城市——新东京。世界仿佛要恢复到以前的繁荣。2019年的一个夜晚，新东京郊外的封闭高速公路上，暴走族团体正在公路上…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (157,'银翼杀手',2,'kh35.jpg','1982','雷德利·斯科特','哈里森·福特 / 鲁格·豪尔 / 肖恩·杨','在一个科技高度发达却因城市与社会凋敝而黯淡的未来，侦探瑞克·戴克奉命追捕叛逃的凶残复制人，同时被一位神秘女子吸引——她的秘密或许将侵蚀他的灵魂。',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (158,'银河护卫队3',2,'kh36.jpg','2023','詹姆斯·古恩','克里斯·帕拉特 / 佐伊·索尔达娜 / 戴夫·巴蒂斯塔','历经一连串宇宙危机后，银河护卫队终于有了暂时安定的家园，但彼得·奎尔依然没有完全走出失去卡魔拉的阴影。就在众人试图开始新的生活时，一场突如其来的袭击让火箭浣熊身受重伤，而他身体中隐藏的秘密又让常规治疗无法挽救他的生命。为了救回这个一路并肩…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (159,'蝙蝠侠：黑暗骑士归来（下）',2,'kh37.jpg','2013','杰伊·欧力瓦','彼得·韦勒 / 艾莉尔·温特 / 大卫·塞尔比','曾经罪恶横行的高谭市，自布鲁斯·韦恩决定以蝙蝠侠的身份归来后，仿佛终于发生了新的变化。变种人头目双面人被除掉，然而原变种人团伙摇身变成蝙蝠狂热者，以暴力的方式执行着对善恶之行的裁断。因此，蝙蝠侠的法外行为引起广泛争论，甚至惊动白宫，而高谭…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (160,'魔女',2,'kh38.jpg','2018','朴勋政','金多美 / 赵敏修 / 朴熙顺','10年前在一起奇怪的事故中独自生还的失忆少女子允，在一对老夫妇的抚养下长大。为了贴补家用，子允参加了某档电视节目，但让她没想到的是，就在节目播出后，开始有各种奇怪的人出现在她面前。',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (161,'星球大战6：绝地归来',2,'kh39.jpg','1983','理查德·马昆德','马克·哈米尔 / 哈里森·福特 / 凯丽·费雪','银河帝国再度建造威力更强大、更坚不可破的“死星”，邪恶的势力又再一次威胁莱娅公主所领导的反抗军。莱娅公主等人前去援救被贾巴囚禁的索罗船长，却失败被贾巴捉住，最后在卢克·天行者的支持下，众人才成功逃出。卢克前往大师尤达的住所，即将离世的尤达…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (162,'银河护卫队',2,'kh40.jpg','2014','詹姆斯·古恩','克里斯·帕拉特 / 佐伊·索尔达娜 / 戴夫·巴蒂斯塔','幼年时被带离地球的彼得·奎尔在掠夺者勇度的抚养下长大，如今以“星爵”之名在宇宙中四处冒险。一次行动中，他偷走了一颗来历不明的神秘球体，却因此成为强大敌人罗南追捕的目标。围绕这件宝物，彼得先后与卡魔拉、赏金猎人火箭浣熊和格鲁特产生冲突，又结…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (163,'V字仇杀队',2,'kh41.jpg','2006','詹姆斯·麦克特格','娜塔莉·波特曼 / 雨果·维文 / 斯蒂芬·瑞','未来的英国社会处于极权统治的高压下，不能容许同性恋者、异教徒等社会角色的存在，人民在黑暗政权下苟延残喘。  这晚，年轻女子艾薇身陷险境，幸得V相助。V是一个永远带着面具的神秘男子，拥有高智商和超凡战斗力。他摧毁了伦敦的标志性建筑，同时也点…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (164,'龙珠超：超级人造人',2,'kh42.jpg','2022','儿玉彻郎','野泽雅子 / 古川登志夫 / 皆口裕子','2022年6月11日上映的《龙珠》第21部剧场版动画，亦是《龙珠超》第2部剧场版动画。故事讲述了曾经被孙悟空击败的红绸军卷土重来，创造出了自称是超级英雄的人造人伽玛1号和伽玛2号。悟饭、比克与两位超级人造人狭路相逢，展开了激烈的对战……红…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (165,'正义联盟：闪点悖论',2,'kh43.jpg','2013','杰伊·欧力瓦','贾斯廷·钱伯斯 / 克里斯托弗·托马斯·豪威尔 / 迈克尔·B·乔丹','本片根据DC漫画2011年的大事件“闪点”改编。闪电侠巴里·艾伦一觉醒来，发现整个世界时间线都被改变了，自己不再是闪电侠，没有了超能力，而年幼时去世的母亲居然活生生站在自己面前。不仅如此，正义联盟也从没存在过，世界即将毁灭于神奇女侠带领的…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (166,'月球旅行记',2,'kh44.jpg','1902','乔治·梅里爱','乔治·梅里爱 / Bleuette Bernon / François Lallement','天文学院院长（乔治·梅里爱 Georges Méliès 饰）在一次会议上提出天马行空的月球旅行计划。他和另五名大胆的天文学家监制出了炮弹舱和大炮，并在军队的帮助下乘坐炮弹舱顺利登月。兴奋过后六名天文学家精疲力竭的在月球表面睡去，浑然不知…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (167,'堤',2,'kh45.jpg','1962','克利斯·马克','Jean Négroni / Hélène Chatelain / Davos Hanich','一個男人在一次實驗中面對自己的過去，試圖找出解決世界大戰所造成的末世問題的方法。',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (168,'怪物少女妮莫娜',2,'kh46.jpg','2023','尼克·布鲁诺 / 特洛伊·奎恩','科洛·葛蕾丝·莫瑞兹 / 里兹·阿迈德 / Eugene Lee Yang','为了证明自己的清白，一名被诬陷犯下重罪的骑士与擅长变形的好斗少女联手。但如果这名少女正是他曾立誓要消灭的怪物，他又该如何是好？',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (169,'天赐灵机',2,'kh47.jpg','2021','Sarah Smith / Jean-Philippe Vine','杰克·迪伦·格雷泽 / 扎克·加利费安纳基斯 / 爱德华·帕克·赫尔姆斯','在一个行走、交谈、数字连接的机器人已经成为孩子们最好的朋友的世界里，《天赐灵机》讲述了一个11岁的男孩发现他的机器人伙伴不太工作的故事。',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (170,'铁血战士：杀戮之地',2,'kh48.jpg','2025','丹·特拉亨伯格','艾丽·范宁 / 迪米特里乌斯·科罗马坦基 / 拉维·纳亚兰','一名外星猎手被所属部族驱逐后，意外与一台受损的机器人结为盟友，随后踏上险象环生的旅程，寻找自己的终极宿敌。',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (171,'她',2,'kh49.jpg','2013','斯派克·琼斯','华金·菲尼克斯 / 斯嘉丽·约翰逊 / 琳恩·A·弗里德曼','故事发生于不远的未来洛杉矶，讲述情感丰沛而复杂的西奥多·托姆布里——他以替人代写真挚书信为生。经历漫长关系终结后的心碎时期，他被一款全新高级操作系统吸引，该系统承诺将成为专属于每位用户的直觉型实体。启动系统后，他欣喜地遇见了“萨曼莎”——…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (172,'金刚狼3：殊死一战',2,'kh50.jpg','2017','詹姆斯·曼戈尔德','休·杰克曼 / 达芙妮·基恩 / 帕特里克·斯图尔特','2029年，变种人大幅减少，X战警早已解散。身心疲惫的金刚狼罗根的自愈因子逐渐消失，整天饮酒度日，靠当司机养家。他在墨西哥边境隐居，并照顾着饱受病痛折磨的老X教授。有一天，一位陌生女子让罗根送一个叫劳拉的女孩去加拿大边境，一开始罗根拒绝了…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (173,'迈克尔·杰克逊：巨星之路',3,'jq13.jpg','2026','安东尼·福奎阿','贾法尔·杰克逊 / 科尔曼·多明戈 / 尼娅·朗','本片将通过一段从未展现过的深度视角，真实记录传奇巨星迈克尔·杰克逊的复杂人生。影片不仅再现了他最具标志性的艺术表演瞬间，更深入挖掘了他的内心世界——从天才神童的成长阵痛到全球偶像背后的争议与坚韧，全面呈现这位伟大艺术家的辉煌与坎坷。',9,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (174,'十二怒汉',3,'jq14.jpg','1957','西德尼·吕美特','马丁·巴尔萨姆 / 约翰·菲尔德 / 李·科布','西德尼·吕美特执导的本片堪称电影史上最颠覆的法庭剧。这部改编自雷金纳德·罗斯电视剧的经典之作，以密室内群像戏的精炼笔法，透视美国司法体系的肌理，张力十足。亨利·方达饰演的异议者，在由白人男性组成的陪审团中孤身抗辩——其余成员皆急于裁定被控…',9,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (175,'绿里奇迹',3,'jq15.jpg','1999','弗兰克·德拉邦特','汤姆·汉克斯 / 大卫·摩斯 / 邦妮·亨特','1935年。美国南部惨淡肃杀的冷山监狱。这里有片一英里长的绿地，人们叫它“绿里”。不过，它的居民皆为死囚，在绿地的另一头，便是行刑用的电椅。保罗·艾治科姆（汤姆·汉 克斯饰）是这里的狱监，对于走过“绿里”、继而在电椅上惨叫毙命的死囚行刑程…',9,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (176,'勇夺芳心',3,'jq16.jpg','1995','Aditya Chopra','卡卓儿 / 沙鲁克·汗 / 阿莫瑞什·普瑞','乔德利和妻子结婚多年，一直十分恩爱。两人共同养育了两个女儿希姆莱和图吉，两个姑娘都出落得亭亭玉立。一晃眼，希姆莱就到了该嫁人的年纪了，尽管乔德利一家人已经在伦敦生活了二十多年了，但乔德利骨子里依旧是一个传统的印度人。乔德利将希姆莱许配给了…',9,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (177,'寄生虫',3,'jq17.jpg','2019','奉俊昊','宋康昊 / 李善均 / 曹汝贞','金基泽一家四口挤在首尔一间狭小的半地下室里，没有稳定工作，只能靠零散的活计勉强维持生活。一天，儿子基宇经朋友介绍，得到前往富裕的朴社长家担任英语家教的机会。进入这个与自己生活截然不同的家庭后，基宇发现了新的机会，并设法将妹妹基婷包装成艺术…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (178,'萤火虫之墓',3,'jq18.jpg','1988','高畑勋','辰巳努 / 白石绫乃 / 志乃原良子','1945年，第二次世界大战接近尾声，日本神户在空袭中化为一片火海。14岁的清太带着4岁的妹妹节子逃过轰炸，却在灾难中失去了母亲，而在海军服役的父亲也远在战场。无家可归的兄妹只得寄住在亲戚家中，但随着战争持续、物资愈发匮乏，寄人篱下的生活也…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (179,'搏击俱乐部',3,'jq19.jpg','1999','大卫·芬奇','爱德华·诺顿 / 布拉德·皮特 / 海伦娜·伯翰·卡特','杰克( 爱德华·诺顿 Edward Norton 饰)是一个充满中年危机意识的人，他非常憎恨自己的生活及一切，再加上他患有严重的失眠症，所以他常常参加各种团体咨询会，只为了能接触人群。在某一个团体咨询会上，杰克遇上了一个跟他同样理由来参加…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (180,'素媛',3,'jq20.jpg','2013','李濬益','薛景求 / 严志媛 / 李蕊','素媛是一个生活在普通家庭里的小女孩，每天在父母的疼爱中平静成长。一个下着雨的早晨，她独自上学途中遭到陌生男子性侵，原本无忧无虑的生活从此被彻底改变。严重的身体伤害和心理创伤让素媛变得恐惧而敏感，甚至一度无法接受父亲的靠近，而突如其来的打击…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (181,'飞越疯人院',3,'jq21.jpg','1975','米洛斯·福尔曼','杰克·尼科尔森 / 布拉德·道里夫 / 路易丝·弗莱彻','在州立精神病院里休养总比蹲监狱强，对吧？兰德尔·P·麦克墨菲（杰克·尼科尔森 饰），一个血管里流淌着闪电、舌绽莲花的自由派骗子，装疯混进了他所谓的“疯子们”中间。很快，他那极具感染力的无序感便与麻木的例行程序发生冲撞。当世界大赛正酣时，这…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (182,'蛊惑兄弟',3,'jq22.jpg','2000','Guel Arraes','马修斯·纳克加勒 / 赛尔顿·梅罗 / 费尔兰德·蒙特纳哥','智高和杰克，一对患难穷兄弟，四出寻找工作，最终在面包店找到差事。但店主极为刻薄，兄弟俩的食物比狗还要差。阴差阳错，他们弄死了店主的狗，更要哄骗神父替小狗祈福，闹出笑话连篇。及后智高暗恋大财主之女路仙霞。但智高过于害羞，久久未能成事；杰克唯…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (183,'声之形',3,'jq23.jpg','2016','山田尚子','入野自由 / 早见沙织 / 悠木碧','西宫硝子（早见沙织 配音）生来患有听觉障碍，要依靠助听器和外界交流，口语发音也因此格外的古怪。小学时，硝子转入了一所新的学校，特殊的生理缺陷让她成为了班上引人注目的独特存在，她因此收获了坚实的友情，却也遭到了以男生石田将也（入野自由 配音…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (184,'天国与地狱',3,'jq24.jpg','1963','黑泽明','三船敏郎 / 仲代达矢 / 香川京子','在黑泽明这部极具影响力的家庭伦理剧与刑侦叙事杰作中，三船敏郎饰演的富商权藤金吾令人过目难忘——其家人沦为冷血绑匪的勒索目标。改编自艾德·麦可班恩侦探小说《国王的赎金》的本片，游刃有余地从分秒必争的惊悚剧过渡为精准的社会剖析，铸就了一部关于…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (185,'加百列的地狱',3,'jq25.jpg','2020','托斯卡·马斯克','Melanie Zanetti / 吉欧里奥·贝鲁蒂 / 库尔特·麦金尼','一个迷人的探索诱惑，禁止的爱，和救赎，一个迷人和激情的故事，一个人从他自己的地狱，因为他试图赢得不可能的宽恕和爱。',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (186,'爆裂鼓手',3,'jq26.jpg','2014','达米恩·查泽雷','迈尔斯·特勒 / J·K·西蒙斯 / 保罗·雷瑟','年轻的爵士鼓手安德鲁·奈曼就读于全国顶尖的音乐学院，师从令人畏惧的爵士乐导师特伦斯·弗莱彻，在成为顶尖爵士鼓手的道路上奋力挣扎。',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (187,'幸运有八只触手',3,'jq27.jpg','2026','奥利维亚·纽曼','莎莉·菲尔德 / 刘易斯·普尔曼 / 科尔姆·米尼科曼','一名寡妇在小镇水族馆值夜班，与一只聪明的章鱼及一个迷茫的年轻人培养出独特情谊。',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (188,'钢琴家',3,'jq28.jpg','2002','罗曼·波兰斯基','阿德里安·布罗迪 / 托马斯·克莱舒曼 / 弗兰克·芬莱','第二次世界大战爆发前夕，波兰犹太裔钢琴家瓦迪斯瓦夫·什皮尔曼仍在华沙电台演奏钢琴。随着德军占领波兰，针对犹太人的迫害不断升级，他和家人被迫迁入华沙犹太区，原本平静的生活也彻底崩塌。在饥饿、暴力与死亡的阴影下，什皮尔曼与家人艰难求生，却又在…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (189,'美国往事',3,'jq29.jpg','1984','赛尔乔·莱昂内','罗伯特·德尼罗 / 詹姆斯·伍兹 / 伊丽莎白·麦戈文','二十年代的美国，纽约少年“面条”和几个同龄朋友一起认识了聪明狡黠的“麦克斯”，他们开始从事走私活动。不久，面条在一场械斗中杀伤人命，被关进监牢。若干年后，“面条”出狱，当时的小伙伴们已经变成了健壮的青年人，在“麦克斯”的带领下，他们开始了…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (190,'加百列的地狱：第二部',3,'jq30.jpg','2020','托斯卡·马斯克','Melanie Zanetti / 吉欧里奥·贝鲁蒂 / James Andrew Fraser','加布里埃尔·爱默生教授终于发现了朱莉娅·米切尔身份的真相，但他的意识到为时已晚。茱莉亚最终希望这位受人尊敬的但丁专家会记住她，并且不想再与他有任何关系。加布里埃尔能在别人的怀抱中找到爱之前赢回她的心吗？',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (191,'激进教学',3,'jq31.jpg','2023','Christopher Zalla','欧亨尼奥·德伯兹 / Daniel Haddad / Jennifer Trejo','在一个充满忽视、腐败和暴力的墨西哥边境小镇，一名老师决定尝试一种激进的新方法来释放学生的潜力与好奇心，甚至发掘出他们的天才之处。',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (192,'后窗',3,'jq32.jpg','1954','阿尔弗雷德·希区柯克','詹姆斯·斯图尔特 / 格蕾丝·凯利 / 温德尔·科里','一位足不出户的摄影师透过公寓窗户窥见邻居们的隐秘生活，当他断定其中一人犯下谋杀罪行时，一场扣人心弦的观察与博弈就此展开。詹姆斯·斯图尔特与格蕾丝·凯利联袂出演这场由阿尔弗雷德·希区柯克执导的、在有限空间内层层铺陈悬念的影史经典。',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (193,'加百列的地狱：第三部',3,'jq33.jpg','2020','托斯卡·马斯克','Melanie Zanetti / 吉欧里奥·贝鲁蒂 / Rhett Wellington Ramirez','一个黑暗的人带着恶意从茱莉亚的过去回来了。加布里埃尔有他需要分享的秘密，但担心如果他这样做，他会失去一切。他们的关系会经受住秘密揭露的考验吗？他们对但丁和弗洛伦斯的共同热爱会是他们所希望的一切吗？',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (194,'真爱留声',3,'jq34.jpg','2026','Leah McKendrick','佐伊·达奇 / 尼克·罗宾森 / 岑勇康','年轻女子给已故姐姐发送的搞笑自白语音留言无意中被转给了陌生人，而这个陌生人竟隔着遥远的距离爱上了她。',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (195,'生之欲',3,'jq35.jpg','1952','黑泽明','志村乔 / 田中春男 / 金子信雄','黑泽明导演生涯的至高成就之一，本片以极致的悲悯凝视死亡，完成对生命的礼赞。志村乔动人诠释胃癌晚期的老公务员渡边勘治，在生命终点踏上追寻意义的旅程。影片以突破性的双段式结构展开，镜头语言浸润着洞察人性本真的人文主义光辉，从多重维度叩问生存的…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (196,'紫罗兰永恒花园 剧场版',3,'jq36.jpg','2020','石立太一','石川由依 / 浪川大辅 / 子安武人','——「爱」究竟是什么？  曾经将「爱」告诉自己、 给予自己的，重要的人。  即使想见，却再也见不到。 永远。 放开了手的、最最重要的那个人。  从事代笔业的她，名字是「薇尔莉特·伊芙加登」。自幼身为士兵参战，没能获得培育心灵机会的她，无法…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (197,'死亡诗社',3,'jq37.jpg','1989','彼得·威尔','罗宾·威廉姆斯 / 罗伯特·肖恩·莱纳德 / 伊桑·霍克','威尔顿预备学院以其沉稳凝重的教学风格和较高的升学率闻名，作为其毕业班的学生，理想就是升入名校。新学期文学老师约翰·基汀（罗宾·威廉姆斯 饰）的到来如同一阵春风，一反传统名校的严肃刻板...',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (198,'献给我的前妻',3,'jq38.jpg','2019','Jorge Ulloa','Raúl Santana / Nataly Valencia / Carlos Alcántara','这部电影讲述了21岁的阿里尔的故事：为筹钱挽回濒临破裂的恋情、与前女友重逢，他决定组建一支摇滚乐队，参加奖金高达一万美元的乐队大赛，这已是他最后的办法——此前，女友因要前往芬兰实习，两人的感情走到了尽头。阿里尔和好友奥尔特加一起举办海选招…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (199,'摩登时代',3,'jq39.jpg','1936','查理·卓别林','查理·卓别林 / 波莱特·戈达德 / 亨利·伯格曼','二十年代的美国处于经济萧条时期，失业率居高不下，工人受尽压榨，成为了大机器生产中的一颗螺丝钉。查理就是一个底层市民，他在一个机器隆隆的厂房里日以继夜地工作，以赚取微薄的收入。重复繁重的工作压得他喘不过气，他把人们的鼻子当成螺丝钉来拧，卷入…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (200,'妥瑞氏与我',3,'jq40.jpg','2025','柯克·琼斯','罗伯特·阿拉马约 / 玛克辛·皮克 / 彼得·穆兰','本片根据社会活动家约翰·戴维森的真实人生经历改编。讲述他从20世纪80年代英国一名被误解的少年，成长为致力于推动人们理解与接纳妥瑞氏综合症的倡导者的故事。约翰在十五岁时被确诊，在逆境中艰难度过动荡的青春期，一步步走向成年。在他人善意的鼓舞…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (201,'我们如此相爱',3,'jq41.jpg','1974','埃托雷·斯科拉','Nino Manfredi / 维托里奥·加斯曼 / 斯特法尼娅·桑德雷莉','安东尼奥（尼诺·曼弗莱迪 Nino Manfredi 饰）、贾尼（维托里奥·加斯曼 Vittorio Gassman 饰）和尼古拉（Stefano Satta Flores 饰）是战争时代的生死之交。战争结束后，他们回归了家乡，开始了各自…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (202,'生活多美好',3,'jq42.jpg','1946','弗兰克·卡普拉','詹姆斯·斯图尔特 / 唐娜·里德 / 莱昂内尔·巴里摩尔','一位天使被派往人间，帮助一位万念俱灰的商人，向他展现假如他从未存在过，生活将会是怎样的光景。',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (203,'日落大道',3,'jq43.jpg','1950','比利·怀尔德','威廉·霍尔顿 / 格洛丽亚·斯旺森 / 埃里克·冯·施特罗海姆','好莱坞的声名终会消散——只需问问诺玛·戴斯蒙德。她曾是影坛传奇，如今已成被人遗忘的旧时代残影。当穷困潦倒的编剧乔·吉利斯误入她那衰败的宅邸，便陷入了她偏执与妄想的罗网。起初看似机遇的邂逅，很快演变为一场危机四伏的困局。这部作品被广泛认为是…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (204,'触不可及',3,'jq44.jpg','2011','埃里克·托莱达诺 / 奥利维埃·纳卡什','弗朗索瓦·克鲁塞 / 奥玛·希 / 安娜·勒尼','富有的菲利普因一场滑翔伞事故导致高位瘫痪，需要招聘一名全职陪护。前来应聘的人络绎不绝，却始终无法让他满意。直到刚刚出狱的德希斯出现，他本无意得到这份工作，只想拿到一张求职被拒的证明，却意外被菲利普选中，开始了一个月的试用期。一个生活优渥、…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (205,'西部往事',3,'jq45.jpg','1968','赛尔乔·莱昂内','克劳迪娅·卡汀娜 / 亨利·方达 / 杰森·罗巴兹','塞尔吉奥·莱昂内的这部不朽史诗，其恢弘堪比取景地纪念碑谷，其气度媲美星光熠熠的杰出演员阵容，其粗粝不羁正如每个孩子想象中的狂野西部。影片围绕一名神秘的口琴客、一位寻找杀父仇人的寡妇、一个亡命之徒以及一名铁路大亨之间错综复杂的关系展开，以恩…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (206,'现代启示录',3,'jq46.jpg','1979','弗朗西斯·科波拉','马丁·辛 / 马龙·白兰度 / 弗雷德里克·福雷斯特','越战期间，威拉德上尉受命执行一项危险任务，深入柬埔寨刺杀一位脱离建制的叛变上校——此人已在当地部落自封神明。',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (207,'光荣之路',3,'jq47.jpg','1957','斯坦利·库布里克','柯克·道格拉斯 / 拉尔夫·米克尔 / 阿道夫·门吉欧','斯坦利·库布里克执导，堪称影史最具震撼力的反战电影之一。柯克·道格拉斯以炽烈演技诠释第一次世界大战期间一位法国上校的形象——当他的士兵因未能完成不可能的任务而被控怯战时，他毅然与军队高层的冷酷权威展开正面对抗。这部以精湛摄影呈现的沉郁之作…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (208,'七号房的礼物',3,'jq48.jpg','2019','Mehmet Ada Öztekin','Aras Bulut İynemli / 妮莎·索菲亚·阿克松古尔 / İlker Aksum','梅莫（阿拉斯·布鲁特·伊涅姆利 Aras Bulut Iynemli 饰）虽然生得人高马大，但却只有相当于6岁孩童一般的智慧，他带着女儿奥瓦（妮莎·索菲亚·阿克松古尔 Nisa Sofiya Aksongur 饰），同奶奶法蒂玛（塞利尔·…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (209,'乔西的虎与鱼',3,'jq49.jpg','2020','田村耕太郎','中川大志 / 清原果耶 / 宫本侑芽','专攻海洋生物学的恒夫，为了实现自己能够亲眼看一下只生活在墨西哥的梦幻鱼群的梦想，日夜不停地在进行着兼职打工。一天恒夫偶然遇见一个女孩坐在轮椅上，失控从斜坡上冲下来。得到了大学生恒夫救了这个女孩。这个女孩叫乔西，自幼便一直坐在轮椅上，她的祖…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (210,'我想吃掉你的胰脏',3,'jq50.jpg','2018','牛岛新一郎','高杉真宙 / 琳恩 / 藤井幸代','“没有名字的我，没有未来的她” 对他人毫无兴趣，总是独自一人读书的高中生“我”。这样的“我”有一天，偶然捡到一册写着《共病文库》的文库本。那是，天真烂漫的班上人气王·山内樱良私下记录的日记本。里面记载着她身患胰脏的疾病，已经时日无多……。…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (211,'奇幻变身大冒险',4,'dh13.jpg','2026','内森·格雷诺','迈克尔·B·乔丹 / 朱诺·坦普尔 / 特雷西·摩根','森林中的一个小生物和一只高贵的鸟突然互换了身体，他们不得不结伴而行，共同应对此生最疯狂的冒险。',9,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (212,'哈尔的移动城堡',4,'dh14.jpg','2004','宫崎骏','倍赏千惠子 / 木村拓哉 / 美轮明宏','18岁少女苏菲在街上遇到神秘青年霍尔，霍尔忽然抱起苏菲一同飞上天空，苏菲的心从此深深地被霍尔吸引。然而那天晚上，苏菲被名叫荒地魔女的女巫施了魔法，外表变成了90岁的老婆婆。心灰意冷的苏菲只好整理行李，远离人群，前往霍尔在荒郊野外的城堡……',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (213,'幽灵公主',4,'dh15.jpg','1997','宫崎骏','松田洋治 / 石田百合子 / 田中裕子','室町时代，生活在偏远村落的少年阿席达卡为了保护族人，与一头被邪魔侵蚀的山猪神交战，却因此受到可怕的诅咒。为了寻找诅咒的来源和活下去的方法，他离开故乡前往西方。在旅途中，阿席达卡来到一片古老森林附近，发现以黑帽大人为首的人类为了炼铁不断开采…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (214,'未麻的部屋',4,'dh16.jpg','1998','今敏','岩男润子 / 松本梨香 / 辻亲八','当红三人少女偶像团体Charming Bird面临解散，核心成员雾越未麻在事务所的安排下不得不退出团体，转型成为一名电视剧演员。万事开头难，对于偶像歌手转型而来的未麻尤其如此，她在工作中承受着压力，闷闷不乐。与此同时，各种恐吓信不断、经纪…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (215,'玩具总动员5',4,'dh17.jpg','2026','安德鲁·斯坦顿','琼·库萨克 / 汤姆·汉克斯 / 蒂姆·艾伦','胡迪、巴斯光年、翠斯等“元老级”玩具将跟随小主人邦妮的成长脚步，共同迎接数字时代下的全新挑战。随着无所不能的科技产品逐渐走进童年世界，一批充满科技感的崭新角色也随之重磅亮相：青蛙造型的智能平板小荷、憨态可掬的导航玩具小不丢、活力十足的抓拍…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (216,'萤火之森',4,'dh18.jpg','2011','大森贵弘','泽田泉 / 田谷隼 / 佐仓绫音','某年夏天，6岁小女孩竹川萤来到爷爷家度假，她闯进了传说住满妖怪的山神森林。正当她因为迷路而焦急万分的时候，一个戴着狐狸面具的大男孩出现在她面前，并引领着萤找到回家的路。虽然萤分外感激，可是男孩却禁止她碰触自己的身体，原来这名叫银的男孩并非…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (217,'青春猪头少年不会梦到怀梦美少女',4,'dh19.jpg','2019','增井壮一','石川界人 / 濑户麻沙美 / 水濑祈','居住在天空与海洋辉映的城镇“藤泽”的梓川咲太，就读高中二年级。INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (218,'狼的孩子雨和雪',4,'dh20.jpg','2012','细田守','宫崎葵 / 大泽隆夫 / 黑木华','在某国立大学念书的花（宫崎葵 配音）与偶然来校旁听的男子（大泽隆夫 配音）坠入爱河，即使对方是一名狼人，她也义无反顾投入对方怀抱。此后的岁月里，花先后生下女儿小雪和儿子小雨。谁知厄运突然降临，温柔的丈夫撒手人寰。柔弱而坚强的花竭尽全力抚养…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (219,'穿靴子的猫2',4,'dh21.jpg','2022','乔尔·克劳福德','安东尼奥·班德拉斯 / 萨尔玛·海耶克 / 哈维尔 吉伦','时隔11年，臭屁自大又爱卖萌的猫大侠回来了！如今的猫大侠（安东尼奥·班德拉斯 配音），依旧幽默潇洒又不拘小节、数次“花式送命”后，九条命如今只剩一条，于是不得不请求自己的老搭档兼“宿敌”——迷人的软爪妞（萨尔玛·海耶克 配音）来施以援手来…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (220,'克劳斯：圣诞节的秘密',4,'dh22.jpg','2019','塞尔吉奥·巴勃罗斯','杰森·薛兹曼 / J·K·西蒙斯 / 拉什达·琼斯','贾斯帕（詹森·舒瓦兹曼饰）被认为是邮政学院最差的学生，他驻扎在北极圈内的一个冰冻岛屿上，那里的当地人之间几乎不交流，更不用说写信了。当贾斯帕准备放弃之时，他找到了自己的盟友阿尔娃（当地的一名教师，拉什达·琼斯饰），并发现了克劳斯（奥斯卡奖…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (221,'超级马力欧银河大电影',4,'dh23.jpg','2026','亚伦·霍瓦特 / 迈克尔·杰勒尼克','克里斯·帕拉特 / 查理·戴 / 安雅·泰勒-乔伊','击败酷霸后，马力欧和路易吉在蘑菇王国开始了新的生活，并结识了新伙伴耀西。与此同时，酷霸Jr.为了救出父亲、重振酷霸家族，将目标指向生活在彗星天文台、守护奇可们的罗莎塔公主。随着碧姬公主的生日庆典被突如其来的危机打破，马力欧、路易吉、碧姬公…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (222,'宇宙小子大电影',4,'dh24.jpg','2019','瑞贝卡·舒格','Zach Callison / Deedee Magno Hall / Estelle','讲述史蒂文以为他保护地球的日子结束了，但新的反派来到沙滩市，史蒂文平静美丽的日子也完了，他遇到了人生中最大的挑战。',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (223,'男孩、鼹鼠、狐狸和马',4,'dh25.jpg','2022','Charlie Mackesy / Peter Baynton','Jude Coward Nicoll / 汤姆·霍兰德尔 / 伊德瑞斯·艾尔巴','查理·麦克西的同名绘本改编的手绘动画，关于善良、友谊、勇气和希望，通过一段辛酸而真挚的旅程，讲述了一个男孩、一只鼹鼠、一只狐狸和一匹马，四个孤独的灵魂在寻找家的过程中结伴而行，并在彼此身上找到了自己存在的意义。',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (224,'蓦然回首',4,'dh26.jpg','2024','押山清高','河合优实 / 吉田美月喜 / 齐藤阳一郎','藤野是一名小学四年级学生，她在校报上连载的四格漫画专栏获得了同学们的一致好评。然而某天她的老师却突然告诉她，逃学的京本想在报纸上刊登自己的漫画。两个女孩对漫画的共同热情让她们走到了一起，直到有一天，某件事的发生打破了这一切，一个令人揪心的…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (225,'狼行者',4,'dh27.jpg','2020','汤姆·摩尔 / Ross Stewart','霍纳·妮芙茜 / Eva Whittaker / 肖恩·宾','在一个充满迷信与魔法的时代，年轻的见习猎人罗宾·古德费洛跟随父亲前往爱尔兰，奉命消灭最后一群野狼。在城墙外的禁忌之地探险时，罗宾结识了无拘无束的女孩梅芙——她来自一个神秘部落，传说其族人能在夜晚化身为狼。在寻找梅芙失踪母亲的过程中，罗宾逐…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (226,'朝花夕誓：于离别之朝束起约定之花',4,'dh28.jpg','2018','冈田麿里','石见舞菜香 / 入野自由 / 樱井优辉','在世界的尽头，住着一群被称为“离别一族”的古老民族：他们拥有着长寿之血和永生不老的面容。在一场外族入侵的战役中，离别一族惨遭灭族，15岁的玛奇亚虽然侥幸逃生，却彻底和朋友失去了联系。孤身一人的她在残骸中拾到了一个普通人家的遗孤，并决定收养…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (227,'鹬',4,'dh29.jpg','2016','Alan Barillaro','未知','皮克斯2016动画长片《海底总动员2》的前贴片，讲述了一只饥饿的小矶鹬，努力克服恐水症，到海浪肆虐的沙滩上觅食的故事。原来成长就是要抛去曾经的视角，才能看到最美的未来',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (228,'辉耀姬物语',4,'dh30.jpg','2013','高畑勋','朝仓亚纪 / 地井武男 / 宫本信子','深山中的一位老竹匠在发光的竹笋中发现了一个只有掌心大小的女孩，并将她带回家与妻子一同抚养。女孩以惊人的速度长大，在山林与田野间度过无忧无虑的童年，也与伙伴舍丸结下深厚情谊。后来，老人又在竹林中接连发现黄金和华美衣物，认定这是上天希望女孩过…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (229,'心灵奇旅',4,'dh31.jpg','2020','皮特·多克特','杰米·福克斯 / 蒂娜·菲 / 格雷厄姆·沃克','乔·加德纳一名中学乐队教师，终于获得在顶级爵士俱乐部演出的机会。但一次意外让他来到“生之彼岸”，在那里他遇见了对人类生活毫无兴趣的灵魂22。为了回到自己的生活，乔试图让22发现活着的美好，也重新思考人生最重要的问题。',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (230,'奇迹少女 纽约篇',4,'dh32.jpg','2020','托马斯·阿斯特鲁克','Anouck Hautbois / Benjamin Bollen / Antoine Tomé','马丽娜是住在现代法国的巴黎少女，因为一次善举获得神秘老人的认可，得到了能变身为超级英雄奇迹少女的力量。同样获得变身能力的还有马丽娜的同班同学艾俊，他是知名设计师之子，因家庭过度保护长期在家自学，第一天上学却阴错阳差使马丽娜误会其恶作剧。双…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (231,'蜗牛回忆录',4,'dh33.jpg','2024','亚当·艾略特','莎拉·斯努克 / 柯蒂·斯密特-麦菲 / 杰基·韦佛','来自奥斯卡获奖动画师亚当·艾略特，这部苦乐参半的回忆录讲述了一位名叫格蕾丝·普德尔的忧郁女人的故事——她收集蜗牛、爱情小说和豚鼠。',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (232,'猫猫的奇幻漂流',4,'dh34.jpg','2024','金兹·兹巴洛迪斯','未知','这是一段关于友谊与生存的动人篇章，将独立动画的创作雄心与想象力推至令人惊叹的高度。这部荣获奥斯卡奖、风靡全球的作品，讲述了一只勇敢的猫在家园被大洪水摧毁后的故事。它与一只水豚、一只狐猴、一只小鸟和一只小狗结伴，共同驾驶小船寻找陆地。在这颗…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (233,'奇迹梦之队',4,'dh35.jpg','2026','泰瑞·迪利','凯莱布·麦克劳克林 / 加布里埃尔·尤尼恩 / 斯蒂芬·库里','主角威尔是只梦想成为职业球手的小山羊，面对向来由猛兽主宰的凶险赛场，队友对他嗤之以鼻，他能否打破偏见，用实力证明小个子也能称霸球场？',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (234,'新神榜：哪吒重生',4,'dh36.jpg','2021','赵霁','杨天翔 / 张赫 / 宣晓鸣','三千年前，天下动荡，人神共遇大劫，不想哪吒的一缕魂魄逃脱天罗地网，世世转世投胎，这一世与东海市酷爱机车的热血青年李云祥人神共生。然而龙族对哪吒恩怨并未善罢甘休，有着哪吒元神的李云祥，亦无法逃脱被龙族赶尽杀绝的宿命。东海危在旦夕，李云祥是否…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (235,'驯龙高手：重回家园',4,'dh37.jpg','2019','蒂姆·约翰逊','杰伊·巴鲁切尔 / 亚美莉卡·费雷拉 / 克雷格·弗格森','故事发生在小嗝嗝与没牙仔分开的五年之后，博克岛一年一度的亲衣节又到了，然而随着小嗝嗝的孩子们的长大，对龙与人曾经那段真挚而深刻的友谊只能通过父母的言语来了解，不免产生了质疑，小嗝嗝为防止孩子们对龙的误解，又能想出怎样的妙招呢？',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (236,'为美好的世界献上祝福！红传说',4,'dh38.jpg','2019','金崎贵臣','福岛润 / 高桥李依 / 雨宫天','本应由于交通事故（!?）导致人生轻易闭幕的游戏迷家里蹲·佐藤和真，事出偶然地带着女神·阿库娅转生到了异世界。“在如同RPG游戏一样的异世界，享受憧憬已久的冒险者生活！目标是勇者！”像这样兴奋了还没多久，转生而来的和真就尽是遇到倒霉的事情。…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (237,'吉尔莫·德尔·托罗的匹诺曹',4,'dh39.jpg','2022','马克·古斯塔夫森 / 吉尔莫·德尔·托罗','伊万·麦克格雷格 / 大卫·布拉德利 / 格雷戈里·曼因','奥斯卡金像奖获奖电影制作人吉尔莫·德尔·托罗对卡洛·科洛迪的经典故事进行了改编：一个牵线木偶神奇地有了生命，为悲伤的木雕师杰佩托带来慰藉。这部异想天开的定格动画电影由吉尔莫·德尔·托罗和马克·古斯塔夫森执导。为了在世界上找到自己的位置，匹…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (238,'玩具总动员',4,'dh40.jpg','1995','约翰·拉塞特','汤姆·汉克斯 / 蒂姆·艾伦 / 唐纳德·杰伊·里克尔斯','在胡迪的带领下，安迪的玩具们一直在他的房间里快乐地生活着，直到安迪的生日将巴斯光年带入这个大家庭。由于害怕自己在安迪心中的地位被取代，胡迪对这位新成员心存忌惮并密谋排挤。然而当各种意外将巴斯和胡迪与主人分离后，这对冤家逐渐学会了搁置分歧、…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (239,'K-Pop 猎魔女团',4,'dh41.jpg','2025','克里斯·阿佩尔汉斯 / 麦琪·康','赵雅顿 / 梅·洪 / 柳智英','Kpop 超级明星鲁米、米拉和佐伊如果不是在座无虚席的体育场举办演唱会，就是在利用自己的秘密身份 — 强悍的恶魔猎人 — 保护粉丝们免受无处不在的超自然威胁。她们必须共同面对迄今为止最强大的敌人：一支魅力难挡、由恶魔伪装的男团组合。',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (240,'至爱梵高·星空之谜',4,'dh42.jpg','2017','休·韦尔奇曼 / DK 韦尔什曼','道格拉斯·布斯 / 罗伯特·古拉奇克 / 埃莉诺·汤姆林森','2015年是梵高的125年诞辰，为了纪念梵高，英国著名的电影工作室BreakThru Films(曾获得奥斯卡奖)和Trademark Films从2012年开始筹拍一部名叫《Loving Vincent》的动画电影，通过动画师手绘的12…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (241,'海洋之歌',4,'dh43.jpg','2014','汤姆·摩尔','David Rawle / 布莱丹·格里森 / Lisa Hannigan','本和他的小妹妹西尔莎——最后一位“海豹童”，踏上了一段穿越古老传说与魔法逐渐消失世界的奇幻旅程，只为重返他们海边的家园。',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (242,'天气之子',4,'dh44.jpg','2019','新海诚','醍醐虎汰朗 / 森七菜 / 本田翼','影片发生在天气错乱、阴雨连绵的时代。离家出走、独自上京闯荡的少年森岛帆高，遇到了同样生存艰难的少女天野阳菜。两人在大城市中相互依赖，并萌生情愫。拥有超能力的“100%晴天女孩”阳菜，为了重现晴天而离奇失踪。但对于帆高而言，哪怕与世界为敌，…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (243,'纸人',4,'dh45.jpg','2012','John Kahrs','John Kahrs / 凯莉·华格伦 / Jeff Turley','《Paperman》由前皮克斯员工，首次做导演的John Kahrs拍摄。影片结合了手绘动画和CG电脑动画，并获得第85届奥斯卡最佳动画短片奖。故事发生在20世纪90年代的纽约，一天早晨，一个在上班途中的男人无意间在地铁站偶遇一名美丽女子…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (244,'飞屋环游记',4,'dh46.jpg','2009','皮特·多克特','爱德华·阿斯纳 / 克里斯托弗·普卢默 / 乔丹·长井','小男孩卡尔从小怀揣着对冒险的向往，并因共同的梦想结识了活泼的艾莉。两人相伴一生，一直希望有朝一日能够前往南美洲的“仙境瀑布”探险，然而直到艾莉去世，这个愿望也始终未能实现。年老后的卡尔决定完成两人曾经的约定，他将成千上万只气球系在自己的房…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (245,'心跳瞬间',4,'dh47.jpg','2017','Beth David / Esteban Bravo','Nick Ainsworth / Kelly Donohue','宁静祥和的校园，红色卷发男孩仓皇跑进画面中，他手足无措，钻入草丛。稍后才发现，原来他看到了自己心爱之人——一个有着黑色头发的男孩。黑发男孩左手拿着一本书在阅读，右手淡定自若抛着苹果，阳光下的他英俊帅气。红发男孩躲在树后，一脸的痴迷与神往。…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (246,'鬼妈妈',4,'dh48.jpg','2009','亨利·塞利克','达科塔·范宁 / 泰瑞·海切尔 / 詹妮弗·桑德斯','本片根据畅销小说改编而成。卡洛琳是一个充满好奇心的女孩，她在新家里发现了一扇神秘的门，通过那扇门，她进入了一个与现实平行的世界。表面看来，这个世界只是现实世界的镜像复制，其中的事物与现实里的几乎一模一样，但却充满了奇幻。在这里卡洛琳碰见了…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (247,'侧耳倾听',4,'dh49.jpg','1995','近藤喜文','本名阳子 / 高桥一生 / 立花隆','正在读初三的月岛雯是个热爱阅读的女孩，她常常在借书卡上看到“天泽圣司”这个名字，因此对这个素未谋面的人产生了好奇。一次偶然的机会，雯来到一家古董店，并逐渐认识了圣司。圣司对制作小提琴的热爱和对梦想的执着深深触动了她，也让一直喜欢写作的雯开…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (248,'风之谷',4,'dh50.jpg','1984','宫崎骏','岛本须美 / 永井一郎 / 纳谷悟朗','在毁灭工业文明的“火之七日”过去一千年后，世界被散发有毒瘴气的“腐海”逐渐覆盖，生活其中的巨大虫群也让幸存的人类时刻面临威胁。依靠海风阻挡腐海孢子的风之谷，是少数仍能安宁生活的地方。风之谷公主娜乌西卡善于御风，并能够感知王虫等生物的心意，…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (249,'大独裁者',5,'xj13.jpg','1940','查理·卓别林','查理·卓别林 / 波莱特·戈达德 / 杰克·奥基','在其备受争议的杰作中，查理·卓别林既尖刻地讽刺了阿道夫·希特勒，又巧妙地颠覆了自身的喜剧形象。在其首部纯有声片中，卓别林以精湛的肢体表现力分饰两角：残酷而滑稽的“托曼尼亚”独裁者，以及被错认成他的善良犹太理发师。凭借杰克·奥克与宝莲·高黛…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (250,'城市之光',5,'xj14.jpg','1931','查理·卓别林','查理·卓别林 / 弗吉尼亚·切里尔 / 弗洛伦斯·李','这部查理·卓别林最受珍爱的作品，亦是其流浪汉形象的终极篇章。在这部无声影片中，身兼编剧、导演与主演的卓别林达到了悲喜交融的新境界：可爱的流浪汉爱上街头卖花的失明少女（弗吉尼亚·切瑞尔诠释出魔幻般的纯真），却被女孩误认为百万富翁。尽管这部大…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (251,'安逸人生',5,'xj15.jpg','1962','迪诺·里西','维托里奥·加斯曼 / 让-路易斯·特林提格南特 / 凯瑟琳·斯巴克','1962年的夏天，罗伯托和布鲁诺结伴去托斯卡纳地区游玩，这两人的性格年龄都大相径庭。罗伯托是个羞涩内向的学生，而布鲁诺则是个精力旺盛、反复无常的中年人。在旅途中两人慢慢熟悉了解，布鲁诺成功人士和上流社会的派头让罗伯托心生艳羡，但同时他也看…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (252,'绿皮书',5,'xj16.jpg','2018','彼得·法雷利','维果·莫特森 / 马赫沙拉·阿里 / 琳达·卡德里尼','1962年，纽约。夜总会因装修暂时停业后，托尼·利普急需寻找一份新工作，并受雇成为知名黑人钢琴家唐·雪利的司机兼保镖。唐·雪利即将展开为期八周的美国南方巡演，而在当时种族隔离与歧视依然严重的南部地区，两人不得不依靠一本为黑人旅行者提供安全…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (253,'桃色公寓',5,'xj17.jpg','1960','比利·怀尔德','杰克·莱蒙 / 雪莉·麦克雷恩 / 弗莱德·麦克莫瑞','C. C. Baxter是纽约一个大公司的小职员，他的单身公寓经常被公司的高层们用去当作幽会的场所，Baxter也因此获得不少升迁的机会。Baxter暗恋着公司的电梯女郎Fran Kubelik，这天他终于鼓起勇气约了她晚上一起去看一出戏…',8,0);
