INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (256,'寻子遇仙记',5,'xj20.jpg','1921','查理·卓别林','查理·卓别林 / 杰基·库根 / 卡尔·米勒','当查理·卓别林决定突破短片形式、创作其首部长片时，他已是国际巨星。本片不仅展现了卓别林职业生涯的转折点——证明了自己是一位严肃的电影导演，它本身亦是默片时代一部极具感染力的杰作。片中，他再次扮演那可爱的流浪汉角色，这次他收养了一个从街头救…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (257,'雨中曲',5,'xj21.jpg','1952','斯坦利·多南 / 吉恩·凯利','吉恩·凯利 / 唐纳德·奥康纳 / 黛比·雷诺斯','1927年，由唐·洛克伍德（吉恩·凯利 饰）和丽娜·雷蒙德（简·哈根 饰）主演的《皇家流氓》在好莱坞首映。由于丽娜刺耳的嗓音无法匹配其夺目的外貌，为了维护明星形象，宣传部只得安排唐一人讲话。首映后，由于钢琴师科斯莫·布朗（唐纳德·奥康纳 …',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (258,'奇爱博士',5,'xj22.jpg','1964','斯坦利·库布里克','彼得·塞勒斯 / 乔治·坎贝尔·斯科特 / 斯特林·海登','斯坦利·库布里克对冷战焦虑的痛苦式幽默诠释，是好莱坞有史以来对人类愚行最尖锐的讽刺之一。千面戏骨彼得·塞勒斯一人分饰三个截然不同的角色：皇家空军上校莱昂内尔·曼德雷克——怯懦地试图阻止一位精神失常的美军将军下令对苏联发动核袭击；优柔寡断且…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (259,'我的朋友们',5,'xj23.jpg','1975','马里奥·莫尼切利','Ugo Tognazzi / 加斯通·莫辛 / 菲利浦·诺瓦雷','内基（酒吧老板）、佩罗齐（记者）、梅兰德里（建筑师）和马斯切蒂（一个破碎的贵族）住在佛罗伦萨。他们从最年轻的时候就成了朋友，每一个空闲的时候，他们都会一起组织复杂而可怕的笑话，或者只是在托斯卡纳游荡。其中一次疯狂的旅行最终会在像萨萨洛里教…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (260,'圣母街上的大人物',5,'xj24.jpg','1958','马里奥·莫尼切利','维托里奥·加斯曼 / Renato Salvatori / Memmo Carotenuto','这是《男人的争斗》（Rififi）的搞笑版。两个小偷带领一群小混混进行一个宏伟的偷盗计划。他们打算从一处公寓挖一个地道，进入附近一家商店，结果地道挖进了公寓的另一个房间，这只是一个小差错。反正这群笨贼该犯的错全犯了，而那个要偷的保险箱似乎…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (261,'热情如火',5,'xj25.jpg','1959','比利·怀尔德','托尼·柯蒂斯 / 杰克·莱蒙 / 玛丽莲·梦露','作为影史最受喜爱的电影之一，比利·怀尔德这部炙手可热的杰作为好莱坞喜剧树立了新标杆。芝加哥乐手乔与杰瑞（托尼·柯蒂斯与杰克·莱蒙贡献了里程碑式的表演）目睹一场黑帮屠杀后，男扮女装混入一支前往迈阿密的女子乐队仓皇逃逸。乐队主唱“蜜糖”凯恩（…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (262,'街角的商店',5,'xj26.jpg','1940','恩斯特·刘别谦','玛格丽特·苏拉文 / 詹姆斯·斯图尔特 / 弗兰克·摩根','在这部浪漫喜剧的试金石之作中，上流社会世故的大师恩斯特·刘别谦将他著名的优雅风格投向了一个新题材：布达佩斯一家简陋皮革制品店里员工们日常的希望、恐惧与心碎。随着圣诞临近，争吵不断的同事阿尔弗雷德·克拉利克与克拉拉·诺瓦克对彼此愈发恼火——…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (263,'还有明天',5,'xj27.jpg','2023','保拉·科泰莱西','保拉·科泰莱西 / 瓦莱里奥·马斯坦德雷亚 / 罗马纳·马乔拉·韦尔加诺','1946年二战后的意大利，女性地位依旧低下。底层女性迪莉娅（宝拉·柯特莱西 饰），每日在丈夫的暴虐下和生活琐碎中艰难生存，唯有女儿玛塞拉、朋友玛丽莎和每日难得的自由踱步是她痛苦生活中的慰藉……这时，迪莉娅意外收到一封神秘信件，一场出逃即将…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (264,'福尔摩斯二世',5,'xj28.jpg','1924','巴斯特·基頓','巴斯特·基頓 / Kathryn McGuire / Joe Keaton','影片的男主角基顿（巴斯特·基顿 Buster Keaton 饰）是一名乡村影院电影放映师，他喜欢阅读侦探类的书籍，经常幻想自己就是一名像福尔摩一样的大侦探。一天，他把价值一元的巧克力糖谎称四元送给女友凯莎琳（Kathryn McGuire…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (265,'华尔街之狼',5,'xj29.jpg','2013','马丁·斯科塞斯','莱昂纳多·迪卡普里奥 / 乔纳·希尔 / 玛格特·罗比','在危机四伏的投资界，掌管史崔顿·奥克蒙公司的乔丹·贝尔福特生活侈靡、实力雄厚。1987年，22岁的乔丹进入罗斯柴尔德公司，从接线员做起，在高级经纪人马克指点下，进入了股票经纪人充满毒品和欲望的世界，半年后因“黑色星期一”，乔丹转投靠贩卖“…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (266,'甜蜜的生活',5,'xj30.jpg','1960','费德里科·费里尼','马切洛·马斯楚安尼 / 安妮塔·艾克伯格 / 阿努克·艾梅','作为史上最受欢迎的意大利导演之票房巅峰作，此片一举将费德里科·费里尼推向国际主流视野——讽刺的是，它恰恰通过尖锐批判明星文化而达成此成就。影片审视罗马奢华光鲜阶层诱人生活方式下的黑暗底色，跟随一位声名狼藉的八卦记者，记录其在聚光灯边缘奔波…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (267,'骗中骗',5,'xj31.jpg','1973','乔治·罗伊·希尔','保罗·纽曼 / 罗伯特·雷德福 / 罗伯特·阿奇博尔德·肖','1936年9月的芝加哥，一名年轻的骗子为给遇害的搭档复仇，与一位骗术大师联手，设局从一名犯罪头目银行家手中赢取巨额财富。',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (268,'爱情假说',5,'xj32.jpg','2026','克莱尔斯坎伦','丽丽·莱因哈特 / 汤姆·贝特曼 / Rachel Marsh','改编自《纽约时报》畅销小说。博士生奥利弗一时冲动，吻了系里最令人生畏的教授亚当·卡尔森。两人因各自都需要一段"假恋情"而走到一起，这段关系演变成了一场关于化学反应的实验，或许这真能解开爱情谜题。',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (269,'我们是贵族',5,'xj33.jpg','2013','Gary Alazraki','Gonzalo Vega / Luis Gerardo Méndez / 卡拉·索萨','这部电影讲述的是一位白手起家的有钱人和他三个游手好闲的子女的故事。这三个年轻人都是二十几岁，靠着老爸的钱过着奢侈的生活，因此老爸导演了一场骗局，让孩子们以为自己已经破产，并带着全家人搬到了一个低收入的贫民区。在那里，孩子们必须要做一件他们…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (270,'地狱',5,'xj34.jpg','2010','Luis Estrada','达米安·阿尔卡扎 / 华金·科西奥 / 埃内斯托·戈麦斯·克鲁兹','本杰明·加西亚，本尼被驱逐出美国。回到家乡，面对一幅黯淡的画面，本尼卷入了毒品业务，他的生活首次出现了壮观的崛起，被金钱、女人、暴力和乐趣所包围。但很快他将发现犯罪生活并不总是兑现承诺。',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (271,'乔乔的异想世界',5,'xj35.jpg','2019','塔伊加·维迪提','罗曼·格里芬·戴维斯 / 托马辛·麦肯齐 / 斯嘉丽·约翰逊','二战时期，男孩乔乔(戴维斯)和母亲(斯嘉丽)生活在纳粹德国统治下，他不知道母亲在家中藏着一个犹太女孩(麦肯齐)，而母亲秘密为抵抗军工作。乔乔渴望加入希特勒青年团，他脑内出了一个颠覆版的希特勒，这个希特勒有魅力、傻傻的、天真可爱，是他的朋友…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (272,'三个男人一只脚',5,'xj36.jpg','1997','Aldo Baglio / Giacomo Poretti / Massimo Venier / Giovanni Storti','Aldo Baglio / Giovanni Storti / Giacomo Poretti','三个有姻亲关系的男人阿多，阿尼和阿莫同时为脾气暴躁，性格独断的岳父做事。阿多和阿尼以结婚数年，阿莫则将与三姐妹中最小的妹妹结婚。  　　某天，岳父要他们三个从米兰运送一位美国雕塑家的作品：一条腿到南部老家，送抵时刚好举行阿莫与小女儿的婚礼…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (273,'淘金记',5,'xj37.jpg','1925','查理·卓别林','查理·卓别林 / 麦克·斯温 / 汤姆·默里','查理·卓别林的喜剧杰作——描绘了在克朗代克追寻财富的淘金者与浪漫邂逅（美丽的乔治亚·海尔）的故事——永远奠定了卓别林及其“流浪汉”形象的标志性地位。影片部分取景于内华达山脉，包含“面包卷之舞”与“煮皮鞋大餐”等传世笑料，本片是一部令人暖心…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (274,'博·伯翰：隔离在家',5,'xj38.jpg','2021','博·伯翰','博·伯翰','这部喜剧特辑由博·伯翰在隔离期间创作、拍摄和表演，他通过新歌和新的见解讲述了不寻常的一年。',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (275,'卡比利亚之夜',5,'xj39.jpg','1957','费德里科·费里尼','朱丽叶塔·马西纳 / François Périer / Franca Marzi','妓女卡比利亚一直梦想和自己的爱人过上甜蜜安稳的日子。然而，单纯善良的她在一开始就被男友骗光了钱，并被推入河中，差点丧命。即使遭遇如此羞辱，她还是对爱情充满希望。一次，她在街上偶遇一个刚和女友吵架的男演员，被他邀请 回家过夜。正当她受宠若惊…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (276,'黑白魔女库伊拉',5,'xj40.jpg','2021','克雷格·吉勒斯佩','艾玛·斯通 / 艾玛·汤普森 / 乔尔·弗莱','影片改编自道迪·史密斯的小说，故事设定在20世纪70年代朋克摇滚革命时期的伦敦，讲述了一个名叫黛伊拉（艾玛·斯通 饰）的年轻骗子的故事。黛伊拉是一个聪明又有创意的女孩，她决心用自己的设计让自己出名。她和一对欣赏她的恶作剧嗜好的小偷交上了朋…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (277,'爱你，西蒙',5,'xj41.jpg','2018','格里格·伯兰蒂','尼克·罗宾森 / 詹妮弗·加纳 / 乔什·杜哈明','每个人都值得拥有一个伟大的爱情故事。但是对一个17岁的高中生「西蒙」来说这一切却是件超复杂的事：第一、没有人知道他是同性恋；第二、他也搞不清楚自己爱上跟他一样有同样困扰的不具名网友到底是何方神圣？？？为了解决这两个大麻烦，西蒙展开一段爆笑…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (278,'椿三十郎',5,'xj42.jpg','1962','黑泽明','三船敏郎 / 仲代达矢 / 小林桂树','三船敏郎以跋扈的姿态与凌厉的咆哮，在黑泽明这部节奏精妙、构图绝伦的影片中演绎出令人叫绝的喜剧效果。作为《用心棒》的诙谐姊妹篇，厌倦世故的武士椿三十郎协助一群天真的年轻武士肃清氏族内部的恶势力，在此过程中彻底颠覆了他们心中“正统”武士的形象…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (279,'星条红与皇室蓝',5,'xj43.jpg','2023','Matthew López','泰勒·扎克哈尔·佩雷斯 / 尼古拉斯·加利齐纳 / 乌玛·瑟曼','本片改编自《纽约时报》同名畅销书，故事围绕美国总统之子亚历克斯和英国王子亨利展开。亚历克斯和亨利的长期不和威胁到了美英两国的关系。当这对冤家被迫“实施阶段性休战”时，他们冰冷的关系开始解冻，他们之间的摩擦也引发了比他们预想中更深刻的关系。',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (280,'东京教父',5,'xj44.jpg','2003','今敏','冈本绫 / 梅垣义明 / 江守彻','圣诞夜，退役自行车选手Gin，跨性别者花，离家出走的少女美由纪三人在东京的雪夜中无所事事。这是，他们发现垃圾堆中有一位哭泣的弃婴。孩子的襁褓中仅有一个酒吧的名片与照片。婴儿的父母身份成了谜团。花想收留孩子，并将孩子取名清子。但另外2人表示…',8,0);
