INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (282,'绵羊侦探团',5,'xj46.jpg','2026','凯尔·巴尔达','休·杰克曼 / 尼古拉斯·布朗 / 尼古拉斯·加利齐纳','影片改编自莱奥妮·斯万的畅销小说。牧羊人乔治最爱给羊群读侦探小说，没想到自己有一天会离奇死亡。他留下的3000万巨额遗产，让每个人貌似都有犯罪动机。警察毫无头绪之时，羊群们决定“不务正业”迈出牧场，追查牧羊人“躺平”真相！它们秉承着遇见麻…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (283,'马戏团',5,'xj47.jpg','1928','查理·卓别林','查理·卓别林 / 阿尔·欧内斯特·加西亚 / 梅尔娜·肯尼迪','在默片时代的收官之作中，查理·卓别林沉醉于马戏艺术，向启发其精湛滑稽表演的杂技艺人和默剧演员致敬。片中，卓别林饰演的流浪汉被误认为扒手，逃入一个巡回马戏团的表演场，很快成为剧团明星，并爱上了剧团的无鞍骑手。尽管拍摄过程众所周知的坎坷，这部…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (284,'天使爱美丽',5,'xj48.jpg','2001','让-皮埃尔·热内','奥黛丽·塔图 / 马蒂厄·卡索维茨 / 吕菲斯','艾米莉（奥黛丽·塔图 Audrey Tautou 饰）有着别人看来不幸的童年——父亲给她做健康检查时，发现她心跳过快，便断定她患上心脏病，从此艾米莉与学校绝缘。随后因为一桩意外，母亲在她眼前突然死去。这一切都毫不影响艾米莉对生活的豁达乐观…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (285,'虎口脱险',5,'xj49.jpg','1966','热拉尔·乌里','布尔维尔 / 路易·德·菲奈斯 / 特里-托马斯','二战期间，英国一架飞机在执行轰炸任务中，被德军击中，几名英国士兵被迫跳伞逃生。他们约好在土耳其浴室见面，并用这次行动的代号“鸳鸯茶”作为接头暗号。他们分别降落在法国巴黎德军占领区的不同地点。大胡子中队长雷金纳德被动物园管理员所救。而另外两…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (286,'将军号',5,'xj50.jpg','1926','克莱德·布鲁克曼 / 巴斯特·基頓','巴斯特·基頓 / 玛丽昂·麦克 / Glen Cavender','美国南北战争时期，北方联军劫走了南方的火车“将军号”。作为“将军号”司机的约翰尼·格雷，不但要抢回心爱的火车，更要夺回心爱女人的心……  　　最终，约翰尼冲入敌人防线，夺回将军号，救出了女友，并把追逐他们的火车“得克萨斯”号诱到洛克河一座…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (287,'惊魂记',6,'xy13.jpg','1960','阿尔弗雷德·希区柯克','安东尼·帕金斯 / 珍妮特·利 / 薇拉·迈尔斯','凤凰城一女秘书卷走客户四万美元公款，仓皇出逃途中入住一家偏僻汽车旅馆。旅馆经营者诺曼·贝茨是位受其母亲支配的年轻人。',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (288,'老男孩',6,'xy14.jpg','2003','朴赞郁','崔岷植 / 刘智泰 / 姜惠贞','女儿生日那天，中年男子吴大修（崔岷植饰）在醉酒回家路上，突遭不明身份的人绑架失踪。就此，他毫无理由地被囚禁在一个神秘的私人监狱中。寻死未果的吴大修，每天看电视，三餐吃煎饺。通过电视，他得知妻子已遭杀害，女儿下落不明，自己更被怀疑为凶手。就…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (289,'控方证人',6,'xy15.jpg','1957','比利·怀尔德','泰隆·鲍华 / 玛琳·黛德丽 / 查尔斯·劳顿','本片改编自阿加莎·克里斯蒂同名小说。  伦敦著名刑案辩护律师韦菲爵士接受了心脏病治疗，但是身体依旧虚弱，第一天回家休养，护士一直严厉监督他服药，并杜绝烟酒。管家为了便于上楼，还专门为他修了电梯。但是，种种关心照顾，对于这位桀骜不驯、牙尖嘴…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (290,'迷魂记',6,'xy16.jpg','1958','阿尔弗雷德·希区柯克','詹姆斯·斯图尔特 / 金·诺瓦克 / 芭芭拉·贝尔·戈迪斯','这部惊悚悬疑片编织出一张令人晕眩的错位身份、激情与谋杀的巨网：患有恐高症的侦探从海湾救起一位神秘金发女郎后，陷入层层迷局。',8,0);
