INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (292,'罗生门',6,'xy18.jpg','1950','黑泽明','三船敏郎 / 京町子 / 志村乔','这部引人入胜的心理惊悚片探讨真相的本质与正义的意义，被广泛视为影史最伟大的作品之一。四名当事人对一名男子的被杀及其妻子遭强奸的事件给出了截然不同的说法，导演黑泽明以极具冲击力的影像和巧妙的闪回手法呈现这段罗生门。这部雄辩的杰作在国际影坛引…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (293,'雨月物语',6,'xy19.jpg','1953','沟口健二','京町子 / 水户光子 / 田中绢代','战国时代，琵琶湖附近的一个小山村里住着源十郎（森雅之饰）和妻子宫木（田中绢代饰），还有妹夫藤兵卫（小泽荣饰）、妹妹阿滨（水户光子）。他们以开小瓷窑、烧制瓷器为生，战乱中，源十郎想趁着战乱发一笔横财，而藤兵卫则想着成为一名武士，出人头地。 …',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (294,'谜一样的双眼',6,'xy20.jpg','2009','胡安·何塞·坎帕内利亚','里卡多·达林 / 索莱达·维拉米尔 / 巴勃罗·拉戈','本杰明·艾斯玻希多（里卡杜·达林 Ricardo Darín 饰）是一名退休的检察官，几十年的司法工作经验让他积攒下诸多素材，而多年前一起奸杀案始终让他念念不忘，他希望将其付梓出版，了却心愿。25年前，23岁的美丽女教师莉莉安娜·科洛托（…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (295,'公民凯恩',6,'xy21.jpg','1941','奥逊·威尔斯','奥逊·威尔斯 / 约瑟夫·科顿 / 多萝西·科明戈','在影史最耀眼的处女作中，时年二十五岁的编导演全才奥逊·威尔斯将有声时代的电影语言熔铸成首部真正意义上的现代电影。影片通过报业巨头查尔斯·福斯特·凯恩（原型为威廉·伦道夫·赫斯特）流星般崛起又骤坠的人生轨迹，不仅淋漓尽致地勾勒出美国式狂傲的…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (296,'第六感',6,'xy22.jpg','1999','M·奈特·沙马兰','布鲁斯·威利斯 / 海利·乔·奥斯蒙 / 托妮·科莱特','麦克（布鲁斯·威利斯 饰）是著名儿童心理学家，却也有始终未能治愈的患者，甚至因此遭到枪杀，这名少年随后也饮枪自毙。这给麦克带来很大心理阴影，一年后他找到另一个症状很像这名患者的男孩柯尔（海利·乔·奥斯蒙 饰），并耐心的做起了他的医生。柯尔…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (297,'怪物',6,'xy23.jpg','2023','是枝裕和','安藤樱 / 黑川想矢 / 柊木阳太','平静的湖畔小镇，疼爱儿子的单亲妈妈早织（安藤樱 饰）、为学生着想的爽直老师保利 （永山瑛太 饰）以及天真烂漫的孩子们本过着安稳的生活，却因为一次校园冲突，发酵酿成轩然大波，惹起社会与媒体的关注。当事态越见严重，竟在一个暴风雨的清晨，两个孩…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (298,'唐人街',6,'xy24.jpg','1974','罗曼·波兰斯基','杰克·尼科尔森 / 菲·邓纳威 / 约翰·休斯顿','杰克·尼科尔森饰演私家侦探杰克·吉特斯，在战前烈日炙烤的南加州阴暗道德泥沼中谋生。受一位美艳社交名媛委托调查其丈夫的婚外情，吉特斯被卷入双重阴谋与致命欺骗的漩涡，揭开个人与政治丑闻交织的罗网——这一切在唐人街那个永生难忘的夜晚轰然交汇。',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (299,'蓝白红三部曲之红',6,'xy25.jpg','1994','克日什托夫·基耶斯洛夫斯基','伊莲娜·雅各布 / 让-路易斯·特林提格南特 / 弗雷德里克·费德','克日什托夫·基耶斯洛夫斯基以宏大篇章为其《蓝白红三部曲》落下帷幕，在《红》中展开一场关于命运与偶然的炽热沉思。伊莲娜·雅各布饰演一位内心纯净却带着忧郁的日内瓦时装模特，她的人生轨迹与让-路易·特兰蒂尼昂饰演的愤世嫉俗的退休法官戏剧性地交汇…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (300,'蝴蝶梦',6,'xy26.jpg','1940','阿尔弗雷德·希区柯克','劳伦斯·奥利弗 / 琼·芳登 / 乔治·桑德斯','浪漫故事在阿尔弗雷德·希区柯克精心雕琢的本片中演变为心理剧，这也是他进军好莱坞的首部作品。影片如梦似幻地改编自达芙妮·杜穆里埃1938年的小说，由迷人的琼·芳登饰演一位年轻女子，她以为自己觅得心之所向，嫁给了风度翩翩的贵族鳏夫迈克西姆·德…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (301,'第三人',6,'xy27.jpg','1949','卡罗尔·里德','约瑟夫·科顿 / 阿莉达·瓦莉 / 特瑞沃·霍华德','低俗小说作家霍利·马丁斯来到阴影笼罩的战后维也纳，却发现自己竟开始调查一位老友——黑市投机者哈里·莱姆的神秘死亡。一段关于爱情、欺骗与谋杀的传奇由此展开。得益于约瑟夫·科顿、阿莉达·瓦利与奥逊·威尔斯的精湛表演，安东·卡拉斯那令人魂牵梦萦…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (302,'记忆之夜',6,'xy28.jpg','2017','张恒俊','姜河那 / 金武烈 / 文成根','真希(姜河那 饰)一家人在一次车祸中，父母丧生，哥哥在医院抢救，需要金钱救治，真希在走投无路的情况下，接到一单以杀人为代价的“生意”，在行凶过程中，由于良知发现，本想放弃行凶，却误杀了目标和她的女儿，真希对此事极度痛苦，选择性的失去了此段…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (303,'恶魔',6,'xy29.jpg','1955','Henri-Georges Clouzot','维拉·克鲁佐 / 西蒙·西涅莱 / 保罗·梅尔瑞斯','德拉萨尔寄宿学校里，女教师克里斯蒂娜和丈夫、校长米歇尔·德拉萨尔感情不偕，德拉萨尔对待他妻子也很粗暴。克里斯蒂娜经过长时间考虑，决定摆脱丈夫，在另一个教师、女友尼古尔的劝说下，她们决定实施一个谋杀计划……',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (304,'利刃出鞘',6,'xy30.jpg','2019','莱恩·约翰逊','丹尼尔·克雷格 / 克里斯·埃文斯 / 安娜·德·阿玛斯','当知名犯罪小说作家哈兰·斯隆比在其85岁生日后不久被发现死于自家庄园时，好奇而风度翩翩的侦探贝努瓦·布兰克被神秘地请来调查此案。从哈兰关系不和的家人到忠诚的仆人们，布兰克在一连串烟雾弹和自私谎言中仔细梳理，以揭开哈兰英年早逝背后的真相。[…',8,0);
