INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (307,'神探夏洛克：可恶的新娘',6,'xy33.jpg','2016','道格拉斯·马金农','本尼迪克特·康伯巴奇 / 马丁·弗瑞曼 / 尤娜·斯塔布斯','《神探夏洛克》（Sherlock）2016年推出特别篇，福尔摩斯回归原著维多利亚时代，调查一宗神秘的幽灵新娘谋杀案。Thomas Ricoletti惊讶地发现，几小时前自杀身亡的妻子Emelia Ricoletti身着旧婚纱再次出现了，她…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (308,'木乃伊',6,'xy34.jpg','2026','李·克洛宁','杰克·雷诺 / 莱娅·科斯塔 / 梅·卡拉美维','讲述一位记者的年幼女儿在沙漠中神秘失踪并音讯全无。八年后，当她突然出现在家人面前时，这个早已破碎的家庭震惊不已；原本应该是重逢的喜悦，却逐渐演变成一场活生生的恶梦。',8,0);
