INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (311,'飞向太空',6,'xy37.jpg','1972','安德烈·塔可夫斯基','娜塔莉亚·邦达尔丘克 / 多纳塔斯·巴尼奥尼斯 / Jüri Järvet','地面控制中心持续收到来自索拉里斯空间站三名幸存宇航员的神秘信号。当宇航员兼心理学家克里斯·凯尔文被派往调查时，他遭遇了与空间站成员相同的奇异现象，由此踏上通往自我意识深处最黑暗角落的旅程。凭借本片，传奇俄罗斯导演安德烈·塔可夫斯基创造了一…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (312,'芬妮与亚历山大',6,'xy38.jpg','1982','英格玛·伯格曼','Pernilla Allwin / Bertil Guve / 简·马尔姆斯','透过十岁少年亚历山大的眼睛，我们见证了艾克达家族的欢欣与纠葛——这个枝叶繁茂的资产阶级家族生活在二十世纪初的瑞典。英格玛·伯格曼将本片视作自己的天鹅之歌，这也是导演最为温情、自传色彩最浓的电影。这部荣获奥斯卡奖的杰作，将他标志性的忧郁与情…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (313,'八恶人',6,'xy39.jpg','2015','昆汀·塔伦蒂诺','塞缪尔·杰克逊 / 库尔特·拉塞尔 / 詹妮弗·杰森·李','寒冷的怀俄明州山谷中，一辆马车载着赏金猎人“绞刑者”约翰·鲁斯 及其价值一万美元的猎物黛西·多摩格 踏雪而行。途中，黑人赏金猎人马奎斯·沃伦少校 和新人警长克里斯·马尼克斯 相继登上马车，红石镇是他们共同的目标。由于风雪太大，马车停在了米…',8,0);
