INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (315,'蝙蝠侠：黑暗骑士归来（上）',6,'xy41.jpg','2012','杰伊·欧力瓦','彼得·韦勒 / 艾莉尔·温特 / 大卫·塞尔比','阴云密布的高谭市，自蝙蝠侠消失的十年里，变种人团伙为非作歹，变本加厉，将这座繁华城市变成充满恐怖和凶杀的罪恶王国。嫉恶如仇的吉姆·戈登探长行将退休，却不免成为变种人下一个袭击的目标。随着双面人哈维·登特走出精神病院，高谭市被带入更加阴冷的…',8,0);
