INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (320,'天使之卵',6,'xy46.jpg','1985','押井守','野田圭一 / 兵藤真子 / 根津甚八','影片架构在一个充满阴影和灰暗色彩的超现实主义世界中，剧情的主角是两个没有提及名字的少年（根津甚八 配音）与少女（兵藤真子 配音）。少女随身带着一颗神秘的蛋，她花许多的时间在某个歌德式的死城里搜集各式瓶子与手工艺品。身上背着一把十字型武器的…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (321,'炎热的夜晚',6,'xy47.jpg','1967','诺曼·杰维森','西德尼·波蒂埃 / 罗德·斯泰格尔 / 沃伦·奥茨','一个从芝加哥来到斯巴达准备建工厂的商人Mr. Colbert被发现死于街头。一个正在火车站等车的黑人Virgil Tibbs（西德尼·波蒂埃 Sidney Poitier 饰）被警察当作嫌疑犯抓到警察局。一番盘查之下，Tibbs告诉当地警…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (322,'史酷比在僵尸岛',6,'xy48.jpg','1998','Jim Stenstrum','Scott Innes / 比利·维斯特 / Mary Kay Bergman','神秘帮会重聚并造访月痕岛，这是一座隐藏着不为人知的秘密的偏远岛屿。达芙妮想要的不仅仅是一个穿着戏服的反派，而且他们得到的比他们想象的要多。',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (323,'烈血大风暴',6,'xy49.jpg','1988','艾伦·帕克','吉恩·哈克曼 / 威廉·达福 / 弗兰西斯·麦克多蒙德','1964年6月21日，三K党徒在美国密西西比州劫持一辆载有三名民权主义者的旅行车，从此他们便失去踪影。为调查他们的下落，联邦调查局派来两名特工人员——艾伦·沃得和鲁珀特·安德森。调查工作进展困难，无论白人或黑人都不对他们说实话。沃德决定派…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (324,'新蝙蝠侠',6,'xy50.jpg','2022','马特·里夫斯','罗伯特·帕丁森 / 佐伊·克拉维茨 / 杰弗里·怀特','布鲁斯·韦恩（罗伯特·帕丁森 饰）化身蝙蝠侠于哥谭市行侠仗义两年后，罪犯皆闻风丧胆，他也因此深入接触到哥谭市的阴暗面。他潜行于哥谭市腐败的政要名流关系网中，身边仅有的几个值得信赖的盟友——管家阿尔弗雷德·潘尼沃斯（安迪·瑟金斯 饰）与詹姆…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (325,'一年中的生活',7,'aq13.jpg','2020','Mitja Okorn','贾登·史密斯 / 卡拉·迪瓦伊 / 小库珀·古丁','泰伦斯·霍华德(《嘻哈帝国》)确认加盟加盟新片[一年中的生活](Life In A Year，暂译)。该片将由Mitja Okorn执导，讲述一个17岁的男孩，在发现患有癌症的女朋友只剩下一年的生命后，决定在她还没离去的这一年给她一个完整…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (326,'五尺天涯',7,'aq14.jpg','2019','贾斯汀·贝尔杜尼','海莉·卢·理查森 / 科尔·斯普劳斯 / 莫伊塞斯·阿里亚斯','17岁女孩Stella和男孩Will身患囊肿性纤维化疾病，他们在医院治疗的过程中相识相爱，两人必须抓紧每分每秒活着的时间。他们的爱情能够战胜疾病和死亡吗？',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (327,'小姐',7,'aq15.jpg','2016','朴赞郁','金敏喜 / 金泰梨 / 河正宇','故事背景设定在1930年代日本占领时期的朝鲜。新人女仆淑熙受雇服侍日本贵族秀子，后者与专横的舅舅居住在一座偏僻的乡间大宅中。然而女仆怀揣秘密：她实为一名扒手，受假冒日本伯爵的骗子招募，企图助其引诱小姐私奔，夺取财产后将秀子关进疯人院。计划…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (328,'20世纪少女',7,'aq16.jpg','2022','方宥力','金裕贞 / 边佑锡 / 朴柾佑','1999年，一名少女为了大犯花痴的好友而密切关注学校里的一个男生，结果却展开了自己的爱情故事。',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (329,'我在雨中等你',7,'aq17.jpg','2019','西蒙·柯蒂斯','凯文·科斯特纳 / 米洛·文提米利亞 / 阿曼达·塞弗里德','影片改编自Garth Stein所著同名畅销小说，聚焦一只名叫恩佐的狗狗，和他的主人——职业赛车手Denny Swift，恩佐跟着Denny学会了很多生活哲学。',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (330,'卡萨布兰卡',7,'aq18.jpg','1943','迈克尔·柯蒂斯','亨弗莱·鲍嘉 / 英格丽·褒曼 / 保罗·亨瑞德','二战期间，卡萨布兰卡是欧洲逃往美国的必经之地，那里鱼龙混杂，局势紧张。里克（亨佛莱•鲍嘉 Humphrey Bogart 饰）是一个神秘的商人，他在卡萨布兰卡开了一家人气很旺的夜总会，并拥有两张宝贵的通行证。一天，反纳粹人士维克多和妻子伊…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (331,'少年的你',7,'aq19.jpg','2019','曾国祥','周冬雨 / 易烊千玺 / 尹昉','高考临近，性格内向的高三学生陈念一心只想考上理想的大学，离开眼前压抑的生活。然而，同校女生胡小蝶的意外坠楼打破了原本紧张却平静的备考生活，也将长期隐藏在校园里的霸凌逐渐暴露出来。此后，陈念也成为以魏莱为首的几名学生欺凌的对象。在她最孤立无…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (332,'燃烧女子的肖像',7,'aq20.jpg','2019','瑟琳·席安玛','诺米·梅兰特 / 阿黛拉·哈内尔 / 卢安娜·巴杰拉米','在十八世纪奢华浪漫的背景下，画家与她的模特之间，激情悄然酝酿，直至两人共同营造一个能容其短暂盛放的天地。本片出自当代法国影坛最受瞩目的作者导演之一——瑟琳·席安玛之手。玛丽安受秘密委派，来到一座与世隔绝的海边庄园，她必须通过暗中观察，为抗…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (333,'请以你的名字呼唤我',7,'aq21.jpg','2017','卢卡·瓜达尼诺','提莫西·查拉梅 / 艾米·汉莫 / 迈克尔·斯图巴','在八十年代的意大利里维埃拉，每年夏天，十七岁的少年埃利奥都会跟家人在这里。今年，和他们共享假日时光的，还有来自美国的奥利弗，高大英俊热情开朗的奥利弗很快就获得了埃利奥一家人的喜爱。随着时间的推移，埃利奥和奥利弗之间渐渐产生了致命的吸引力，…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (334,'特殊的一天',7,'aq22.jpg','1977','埃托雷·斯科拉','索菲亚·罗兰 / 马切洛·马斯楚安尼 / 约翰·弗农','特殊的一天是指1938年5月6日，这天希特勒与墨索里尼在罗马进行所谓的“高峰会议”，整个罗马城里的电台日夜都在鼓吹法西斯的威力和成就，罗马全体居民都放假一天来到广场集合听讲话。中年妇女安东尼泰是个本分的家庭妇女，这天她因照顾孩子操忙家务而…',8,0);
