INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (338,'灿烂人生',7,'aq26.jpg','2003','马可·图利欧·吉欧达纳','路易吉·洛·卡肖 / 阿莱西奥·博尼 / 阿德里娅娜·阿斯蒂','这部跨越四十载（从动荡的1960年代直至当代）的澎湃史诗，跟随一对意大利兄弟穿越意大利近代史上最跌宕起伏的历史事件。[米拉麦克斯]',8,0);
