INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (342,'夜',7,'aq30.jpg','1961','米开朗基罗·安东尼奥尼','马切洛·马斯楚安尼 / 让娜·莫罗 / Monica Vitti','这是发生在米兰的一对夫妻的故事。Giovanni Pontano（马塞洛•马斯楚安尼 Marcello Mastroianni 饰）是一个有名的作家，他有一个美丽的妻子Lidia（让娜•莫罗 Jeanne Moreau 饰）。他们来到医院…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (343,'爱，简单',7,'aq31.jpg','2014','Daniel Ribeiro','Ghilherme Lobo / Fábio Audi / Tess Amorim','女孩吉瓦娜（Tess Amorim 饰）和男孩里奥（Ghilherme Lobo 饰）是最要好的朋友。里奥虽然双目失明，但内心一直渴望自立，不喜欢来自父母的过多保护。新来转校生加百列（Fabio Audi 饰）不小心闯入里奥的世界，也改变…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (344,'邮差',7,'aq32.jpg','1994','迈克尔·雷德福','Massimo Troisi / 菲利浦·诺瓦雷 / 玛丽亚·格拉齐亚·库奇诺塔','在意大利海岸外的一座小岛上，一位年轻邮差的生活因开始为流亡诗人巴勃罗·聂鲁达送信而发生了改变。',8,0);
