INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (346,'金氏漂流记',7,'aq34.jpg','2009','李海俊','郑在泳 / 郑丽媛 / 梁美京','金盛瑾因事业受挫、债台高筑，生活也陷入低谷，对人生彻底失去希望的他从汉江大桥纵身跃下，却意外活了下来，并漂到汉江中央的一座无人小岛。几次脱身失败后，他逐渐放弃自杀的念头，开始利用岛上的植物和城市漂来的废弃物独自求生，在繁华都市近在咫尺的地…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (347,'爱的曝光',7,'aq35.jpg','2008','园子温','西岛隆弘 / 满岛光 / 安藤樱','这部长达近四个小时的电影讲述了一个根据真人真事改编的究极纯爱故事。角田优生长在虔诚的基督徒家庭。母亲早逝，优和当神父的父亲哲过着平淡而幸福的生活。优憧憬着有朝一日能遇到理想中的女性——和母亲气质相似的“玛丽亚”。某天，美艳奔放的薰闯入了这…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (348,'舞台春秋',7,'aq36.jpg','1952','查理·卓别林','查理·卓别林 / Claire Bloom / 奈杰尔·布鲁斯','查理·卓别林这部精湛刻画昔日杂耍明星迟暮岁月的动人戏剧，堪称这位编导大师最为深情之作。卓别林饰演的卡韦罗曾是备受爱戴的音乐喜剧演员，如今沦为蜗居伦敦小公寓的过气酒鬼。当他遇见楼下那位美丽而忧郁的芭蕾舞者时，人生终于透进一丝微光。这部悲喜交…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (349,'恋恋笔记本',7,'aq37.jpg','2004','尼克·卡萨维茨','瑞恩·高斯林 / 瑞秋·麦克亚当斯 / 吉娜·罗兰兹','一个浸润着鲜红与纯白的爱情故事，写在一本洒满昏黄的笔记本上，被一位老先生(詹姆斯·加纳 饰)，一遍一遍的讲述。老太太(吉娜·罗兰兹 饰)总是静静的听着，好奇的追问结果。在一家疗养院，这样不变的场景每天都会上演。笔记本上，秀美的字迹，记载着…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (350,'健听女孩',7,'aq38.jpg','2021','夏安·海德','艾米莉亚·琼斯 / 玛莉·马特林 / 特洛伊·科特苏尔','故事聚焦一个聋哑家庭中唯一有听觉的高中女孩鲁比，她每天都要帮助父母和哥哥操持渔业生意，在加入高中合唱团后，鲁比对歌唱的热爱打动了合唱团长，团长决定让鲁比在梦想和家族之间做一个选择。',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (351,'初恋这首情歌',7,'aq39.jpg','2016','约翰·卡尼','福迪亚·瓦尔什-匹罗 / 露西·博因顿 / 杰克·雷诺','80年代的爱尔兰，14岁男孩康纳（昵称“宇宙”）在学校倍受同学欺负，只好从音乐中寻找慰籍。“宇宙”喜欢上了比他高一级的女孩拉菲娜，同时欣喜的发现她也是个音乐迷。为了打动拉菲娜，完全不会演奏任何乐器的“宇宙”决定组建乐队，并拍摄音乐录影带。…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (352,'想哭的我戴上了猫的面具',7,'aq40.jpg','2020','柴山智隆 / 佐藤顺一','志田未来 / 花江夏树 / 山寺宏一','爱知县常滑市，中学2年级学生笹木美代与日之出贤人是同班同学，但两人之间却有着捉摸不到的距离感。有一天笹木获得了能变成猫的不可思议的面具，变成猫的她与日之出的距离得以接近。',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (353,'千年女优',7,'aq41.jpg','2002','今敏','庄司美代子 / 小山茉美 / 折笠富美子','60岁的立花源也和28岁的摄影师井田恭二不远千里跋山涉水上门去拜访隐居了三十年的一代影星藤原千代子，为了给她拍摄一生自传的纪录片。款款前来的千代子虽已75岁高龄，但仍然优雅美丽，左眼下标志性的小痣也仍然俏皮。立花双手递上一把钥匙，千代子深…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (354,'美丽心灵',7,'aq42.jpg','2001','朗·霍华德','罗素·克劳 / 詹妮弗·康纳利 / 艾德·哈里斯','这是一部关于一个真实天才的极富人性的剧情片。英俊而又十分古怪的数学家小约翰纳什念研究生时便发明了他著名的博弈理论，短短26页的论文在经济、军事等领域产生深远的影响，他开始享有国际声誉。但纳什出众的直觉受到了精神分裂症的困扰，使他向学术上最…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (355,'码头风云',7,'aq43.jpg','1954','伊利亚·卡赞','马龙·白兰度 / 爱娃·玛丽·森特 / 卡尔·马尔登','马龙·白兰度演绎其生涯代表作，饰演由退役拳击手转行的码头工人特里·马洛伊。这部城市诗篇般的杰作，以粗粝而情感澎湃的笔触描绘个体挫败与社会腐败。随着当局逐渐逼近，特里陷入日益深重的道德危机——他必须在忠于与黑帮勾结的工会头目约翰尼·弗兰德利…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (356,'谁可以这样爱我',7,'aq44.jpg','2022','D.J.卡鲁索','阿比盖尔·考恩 / 汤姆·刘易斯 / 埃里克·迪恩','电影以1850年代加州淘金热为背景，讲述了一对年轻夫妇的爱情与残酷的现实之间的冲突。本片改编自法兰辛·里弗斯的同名小说。',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (357,'许愿神龙',7,'aq45.jpg','2021','克里斯·阿佩尔汉斯','黄谷悦 / 约翰·赵 / 吴恬敏','都市少年意外召唤出一只远古神龙，蛰伏已久的神龙竟然要求少年必须向自己许愿。这只与众不同的粉毛神龙突然降临，将与少年展开怎样的冒险之旅?而神龙的幸运之力，又将为人间带来哪些好运?',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (358,'小妇人',7,'aq46.jpg','2019','格蕾塔·葛韦格','西尔莎·罗南 / 艾玛·沃森 / 弗洛伦丝·皮尤','影片汲取路易莎·梅·奥尔科特的经典小说与其创作生涯的双重灵感，以作者的化身——乔·马奇对其虚构人生的往复追忆展开叙事。在编剧兼导演格蕾塔·葛韦格的诠释中，马奇家四姐妹各执决心、追寻自我的动人故事，既焕发着历久弥新的永恒光辉，亦激荡着与当下…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (359,'一夜风流',7,'aq47.jpg','1934','弗兰克·卡普拉','克拉克·盖博 / 克劳黛特·科尔伯特 / 沃尔特·康诺利','在这部由弗兰克·卡普拉打造的浪漫公路喜剧中，截然相反的两人以磁石般的吸引力彼此靠近——一位骄纵逃家的富家女（克劳黛·考尔白 饰）与一位玩世不恭的平民记者（克拉克·盖博 饰）相遇，后者一心要挖掘她失踪背后的绯闻真相。作为影史首部一举囊括奥斯…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (360,'万物理论',7,'aq48.jpg','2014','詹姆斯·马什','埃迪·雷德梅恩 / 菲丽希缇·琼斯 / 查理·考克斯','影片讲述霍金卢伽雷氏症病情发作前的生活，主要关注点在霍金和他妻子之间的故事。由埃迪·雷德梅恩饰演霍金，而菲丽希缇·琼斯饰演他的首任夫人——简。影片从霍金的爱情生活切入，讲述性格内向、整日沉迷物理研究和瓦格纳歌剧的霍金在剑桥大学与简相遇、相…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (361,'空房间',7,'aq49.jpg','2004','金基德','李丞涓 / 在熙 / 权赫浩','泰石（在熙饰）是个无所事事的年轻人，他每天骑着摩托车挨家发传单，将它塞入钥匙孔中。如果过几天传单还没有被人拿掉，泰石就会撬开锁进去小住一段时间，在那洗澡做饭拍照。作为交换，他会帮主人家做些家务、打理房间。一次，他在一所空房子里遇见了一个被…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (362,'最佳出价',7,'aq50.jpg','2013','朱塞佩·托纳多雷','杰弗里·拉什 / 吉姆·斯特吉斯 / 西尔维娅·侯克斯','影片是一部将背景设置在奥地利维也纳奢华的艺术品拍卖行业中的爱情故事，同时也是一部“没有谋杀案的惊悚片”。由英国演员吉姆·斯特吉斯同荷兰女星西尔维娅·侯克斯出演这对年轻的情侣，而澳洲演技派杰弗里·拉什扮演一名介入这段感情当中的神秘的老者。',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (363,'非常嫌疑犯',8,'fz13.jpg','1995','布莱恩·辛格','史蒂芬·鲍德温 / 加布里埃尔·伯恩 / 本尼西奥·德尔·托罗','美国加州的圣佩雷罗港一艘货轮爆炸，死亡27人，9000万美元失踪。事故发生以后，联邦调查局探员白基奇在医院等待昏迷不醒的幸存者；海关特派员大卫（查兹•帕明特里 饰）则对另外一名拿到特赦令的幸存者金特（凯文•史派西 饰）进行了审问。金特供认…',8,0);
