INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (369,'一封关于父亲的信',8,'fz19.jpg','2008','Kurt Kuenne','Kurt Kuenne / Andrew Bagby / David Bagby','本片是一部极具个人色彩的纪录片，深情而强烈地讲述了柯特挚友被谋杀的案件，以及随后发生的、令人难以置信的法律与情感疯狂。[Oscilloscope Pictures]',8,0);
