INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (371,'精英部队',8,'fz21.jpg','2007','何塞·帕迪里亚','瓦格纳·马拉 / 安德烈·拉米罗 / 卡约·容凯拉','时1997年，教皇即将来此视察，高层要求纳斯西蒙（Wagner Moura 饰）所率领的这支精英部队在最短时间内肃清贫民窟内的毒品链。厌倦刀光血影的纳斯西蒙将心思放在了妻子和尚未出世的婴儿身上，他将任务交给了两个热血且充满理想的年青人——…',8,0);
