INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (374,'猫鼠游戏',8,'fz24.jpg','2002','史蒂文·斯皮尔伯格','莱昂纳多·迪卡普里奥 / 汤姆·汉克斯 / 克里斯托弗·沃肯','父母婚姻破裂后，尚未成年的弗兰克·阿巴内尔离家出走，并凭借过人的伪装能力和伪造支票的手段四处行骗。他先后冒充飞行员、医生和律师，在不同身份之间游刃有余，并骗取了数百万美元。与此同时，FBI探员卡尔·汉拉蒂逐渐锁定了这个年轻而狡猾的骗子，并…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (375,'杀死比尔',8,'fz25.jpg','2003','昆汀·塔伦蒂诺','乌玛·瑟曼 / 刘玉玲 / 薇薇卡·福克斯','这是一部令人眼花缭乱，绝对能带给您感官刺激的动作电影。一个新娘（乌玛•瑟曼Uma Thurman饰）在自己的婚礼上遭到了暗杀，婚礼瞬间变成了一片狼籍的红色。幸运的是，新娘并没有就此消失，而是在四年后苏醒过来，并且接受了高强度的各种各样的武…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (376,'猜火车',8,'fz26.jpg','1996','丹尼·博伊尔','伊万·麦克格雷格 / 艾文·布莱纳 / 约翰尼·李·米勒','如一剂直击1990年代英国电影心脏的肾上腺素，这部改编自欧文·威尔士小说的黑色幽默作品，是导演丹尼·博伊尔、制片人安德鲁·麦克唐纳与编剧约翰·霍奇的重要突破。凭借通电般的能量与风格化的胆识，本片跃动穿梭于苏格兰海洛因成瘾者马克·雷顿（伊万…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (377,'盗火线',8,'fz27.jpg','1995','迈克尔·曼','阿尔·帕西诺 / 罗伯特·德尼罗 / 方·基默','文森特•汉纳是洛杉矶警局重案组的探长，工作积极投入，打击犯罪毫不手软，因此，家庭生活危机重重，目前的第三次婚姻也面临解体；尼尔•麦考利是职业匪徒，混迹江湖多年，做事干净利落，而且心狠手辣，不留后患，组织手下成功抢劫运钞车的案子，使他受到了…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (378,'自由作家',8,'fz28.jpg','2007','理查德·拉格拉文斯','希拉里·斯万克 / 帕特里克·登普西 / 斯科特·格伦','爱林（希拉里·斯万克 Hilary Swank饰）从事的第一份教育工作，就是在威尔逊学校一个糟糕透顶的班级里担任老师。这里有着给老师们带来噩梦的学生：他们虚度光阴，消磨时辰，把学校当成18岁之前的游乐场；更混乱的是，学生们来自社会里的不同…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (379,'卡里加里博士的小屋',8,'fz29.jpg','1920','罗伯特·维内','Werner Krauß / 康拉德·维特 / Friedrich Fehér','德国小镇，面目狰狞的卡里加里博士（沃纳·克劳斯 Werner Krauss饰）终于获准表演催眠术。大学生弗朗西斯（弗里德里希·费赫尔 Friedrich Feher饰）和艾伦（汉斯·海因里希 Hans Heinrich von Tward…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (380,'夺魂索',8,'fz30.jpg','1948','阿尔弗雷德·希区柯克','詹姆斯·斯图尔特 / 约翰·达尔 / 法利·格兰杰','博兰顿和菲利普都是哈佛的高才生，一天，都是同性恋的两人合谋杀害了同学戴维，并藏尸于一个大箱子中。或许是出于炫耀，他们做出了一个惊人的举动。那就是用装着戴维尸体的箱子当餐桌，邀请了戴维的父母、未婚妻、同学和茹伯特教授来赴宴。他们谎称戴维外出…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (381,'布朗克斯的故事',8,'fz31.jpg','1993','罗伯特·德尼罗','罗伯特·德尼罗 / 查兹·帕尔明特瑞 / 李洛·布兰卡托','1960年代，纽约意大利人集结的布朗克斯区。黑帮老大辛尼（查兹·帕尔明特瑞 Chazz Palminteri饰）是当地赫赫有名的帮会人物。在一宗凶杀案现场，九岁的男孩安奴（弗朗西斯·卡普拉 Francis Capra饰）目睹了这一切。为了…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (382,'恶人传',8,'fz32.jpg','2019','李元泰','马东石 / 金武烈 / 金成圭','一个雨夜里，凶狠的宙斯帮老大张东秀正开车回家，路上突然被人撞了一下。他刚下车就遭到了毫无预警的袭击，身负重伤的他迅速回击才勉强捡回一条命，但是作为黑帮老大的名声却受到了重创。唯一修复自己名声的办法，就是找到攻击自己的凶手再狠狠地报复回去。…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (383,'洞',8,'fz33.jpg','1960','雅克·贝克','迈克尔·康斯坦丁 / Jean Keraudy / Philippe Leroy','在巴黎的一间牢房里，五名囚犯用尽全部的坚韧与智慧，试图通过精心挖掘的隧道重获自由。根据若泽·乔瓦尼的小说改编，雅克·贝克的这部影片在诗意的人文关怀与紧绷得令人窒息的危险氛围间取得了精妙的平衡。',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (384,'黑帮悍将',8,'fz34.jpg','1993','泰勒·哈克福德','达米安·查帕 / 杰西·博雷戈 / 本杰明·布拉特','影片以诗人吉米·圣地亚哥·巴卡的真实生活经历为基础，重点讲述了帕科和克鲁兹的同父异母兄弟，以及他们的两个种族表兄米科。影片于1972年开拍，因为这三人是洛杉矶东部一个叫“瓦托斯机车”的团伙的成员，故事的重点是暴力犯罪和毒品的影响如何改变他…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (385,'囚徒',8,'fz35.jpg','2013','丹尼斯·维伦纽瓦','休·杰克曼 / 杰克·吉伦哈尔 / 维奥拉·戴维斯','为了自己孩子的性命你会做到哪一步？凯勒.多佛 面对的是每个父母最恐惧的恶梦。他六岁的女儿安娜和小玩伴祖儿一起失踪了。唯一的线索是早前停在他家附近的一辆休闲车。在调查中，警探洛基 逮捕了这辆车的车主亚历克斯.琼斯，但因为缺乏证据而不得不放了…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (386,'你给的仇恨',8,'fz36.jpg','2018','小乔治·蒂尔曼','阿曼德拉·斯坦伯格 / 雷吉娜·赫尔 / 罗素·霍恩斯比','斯塔尔·卡特不停地在两个世界之间切换：她所居住的贫穷、以黑人为主的社区，与她所就读的富裕、以白人为主的预科学校。这两个世界之间脆弱的平衡，在她亲眼目睹童年挚友卡里尔被一名警察开枪射杀后彻底崩塌。如今，面对来自社区各方的压力，她必须找到自己…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (387,'被遗忘的人们',8,'fz37.jpg','1950','路易斯·布努埃尔','Estela Inda / Miguel Inclán / Alfonso Mejía','一群少年犯在墨西哥城臭名昭著的贫民窟中过着暴力的生活，其中年轻的佩德罗（Pedro）的道德观逐渐被其他人腐蚀和摧毁。',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (388,'三块广告牌',8,'fz38.jpg','2017','马丁·麦克唐纳','弗兰西斯·麦克多蒙德 / 伍迪·哈里森 / 山姆·洛克威尔','本片是奥斯卡奖提名者马丁·麦克唐纳执导的一部黑色喜剧犯罪剧情片。在女儿遇害案悬置数月仍未破获后，米尔德丽德·海斯采取了一项大胆之举：她租下通往小镇路上的三块广告牌，牌上直指当地德高望重的警察局长比尔·威洛比的尖锐标语掀起轩然大波。而当威洛…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (389,'相信我：被诱拐的丽莎·麦克维',8,'fz39.jpg','2018','Jim Donovan','凯蒂·道格拉斯 / 大卫·詹姆斯·艾略特 / 罗西夫·萨瑟兰','一名17岁的少女在她计划自杀的当晚被绑架，她必须为活下去而战斗。她设法说服袭击者放过她，在经过26小时后等来了生机。但当她回家时，除了一名怀疑凶手为连环杀手的侦探外，没有人相信她的故事。',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (390,'无知的声音',9,'zz1.jpg','2005','Luis Mandoki','Carlos Padilla / Xuna Primus / 蕾奥娜·维埃拉','20世纪80年代伊始，位于中美洲北部的小国萨尔瓦多爆发长达12年的内战。政府军和游击队连年激战，人民流离失所，国家破败不堪。11岁的男孩恰瓦（Carlos Padilla 饰）和母亲、姊妹生活在一起，他的父亲背井离乡，杳无音信。家中的生活…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (391,'无耻混蛋',9,'zz2.jpg','2009','昆汀·塔伦蒂诺','布拉德·皮特 / 梅拉尼·罗兰 / 克里斯托弗·瓦尔兹','故事分五章进行。二战中德占法国，德军上校汉斯（克里斯托弗·瓦尔兹 Christoph Waltz 饰）号称“犹太猎人”，在一次屠犹行动中，少女苏珊娜（梅勒尼·劳伦特 Mélanie Laurent 饰）侥幸逃脱。与此同时，八名美国犹太士兵…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (392,'自己去看',9,'zz3.jpg','1985','埃莱姆·克利莫夫','阿列克谢·叶夫根耶维奇·克拉夫琴科 / Ольга Миронова / Liubomiras Laucevičius','这是一部很特殊的战争题材电影，它真实地描写了德占区人民的悲惨遭遇和场面，以及人们面对突如其来的灾难的恐惧，反映了战争的真实面目。它既不同于《斯大林格勒保卫战》、《攻占柏林》这些正面战场的血肉横飞、排山倒海、摧枯拉朽，也不同与《这里的黎明静…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (393,'全金属外壳',9,'zz4.jpg','1987','未知','未知','越战期间，加入海军陆战队的一群年轻人被剃了光头，并分配寝位，负责训练他们的上校时常羞辱他们，还给他们取难听的外号，“傻瓜比尔"由于是胖子，动作老是出错，因此成为最经常被上校修理的人。班长“小丑"耐心照顾他。但傻瓜比尔再次的失误，令上校愤怒…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (394,'从海底出击',9,'zz5.jpg','1981','沃尔夫冈·彼得森','尤尔根·普罗奇诺 / 赫贝特·格勒内梅厄 / 克劳斯·温纳曼','1942年，德国潜艇舰队深陷所谓的“大西洋战役”，旨在袭扰并摧毁英国航运。然而，随着驱逐舰级护航力量的加强，德国U型潜艇开始遭受重创。本片讲述了一艘U型潜艇船员的故事，聚焦这些潜艇兵如何保持军人职业素养，执行近乎不可能的任务，同时始终试图…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (395,'奥本海默',9,'zz6.jpg','2023','克里斯托弗·诺兰','基利安·墨菲 / 艾米莉·布朗特 / 马特·达蒙','改编自凯·伯德和马丁·J·舍温合著的传记作品《美国普罗米修斯：J·罗伯特·奥本海默的胜利与悲剧》。理论物理学家J·罗伯特·奥本海默领导曼哈顿计划，研制出世界上第一颗原子弹，彻底改变了历史进程。',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (396,'罗马，不设防的城市',9,'zz7.jpg','1945','罗伯托·罗西里尼','Aldo Fabrizi / 马塞洛·帕格利罗 / Harry Feist','二次大战结束前夕，占领罗马的德军仍大肆搜捕游击队。遭到追捕的地下党员工程师曼发弟逃出来，又在平娜的帮助下见到了唐 皮得罗神父，请神父将一笔巨款交给游击队。德军包围了平娜家，向逮捕曼发弟，神父镇静的应付德军，德军只抓走了平娜就要嫁给的工人弗…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (397,'阿拉伯的劳伦斯',9,'zz8.jpg','1962','大卫·里恩','彼得·奥图尔 / 亚历克·吉尼斯 / 安东尼·奎恩','大卫·里恩1962年的史诗巨制。彼得·奥图尔在此献上了影史中最震撼人心的银幕首秀之一，其饰演的传奇人物劳伦斯在广袤沙漠中交织着理想主义与身份迷失的壮阔篇章，至今仍闪耀着不朽的光芒。',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (398,'1917',9,'zz9.jpg','2019','萨姆·门德斯','乔治·麦凯 / 迪恩-查尔斯·查普曼 / 马克·斯特朗','1917 年，第一次世界大战进入最激烈之际，两个年仅 16 岁的英国士兵接到的命令，需立即赶往死亡前线，向那里的将军传达一个“立刻停止进攻”讯息。 时间只有八小时，武器弹药有限，无人知晓前方敌况：死亡寂静之地、布满尸体的铁丝网、突入其来的…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (399,'模仿游戏',9,'zz10.jpg','2014','莫腾·泰杜姆','本尼迪克特·康伯巴奇 / 凯拉·奈特莉 / 马修·古迪','改编自安德鲁·霍奇斯的传记《艾伦·图灵：谜》。二战期间，数学家艾伦·图灵加入英国绝密密码破译小组，设计机器破解德国“恩尼格玛”密码，在拯救无数生命的同时，也经历了战后人生的悲剧。',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (400,'太极旗飘扬',9,'zz11.jpg','2004','姜帝圭 / Kang Je-gyu','张东健 / 元斌 / 李恩宙','李镇泰是生活在汉城的一个修鞋匠，一家人的生计就从修补鞋子的费用维持。虽然物质并不富裕，这却是一个十分温馨完整的家庭。妻子李英顺和母亲开一间面馆，平日还要照顾下面的弟妹，弟弟李镇锡是家中所有的希望，如今正在高中读书，考上大学是他的梦想，更是…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (401,'猎鹿人',9,'zz12.jpg','1978','迈克尔·西米诺','罗伯特·德尼罗 / 克里斯托弗·沃肯 / 约翰·卡扎尔','本片追踪了一群钢铁工人伙伴——从宾夕法尼亚州的熔炉到阿勒格尼山脉清凉的猎场，再到越南致命的战争熔炉。罗伯特·德尼罗出色地饰演了迈克尔，这群人天生的领袖。本片是一部关于友谊与勇气的灼热戏剧——以及在艰难困苦中这些品质将经历怎样的考验。[环球…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (402,'勇敢的心',9,'zz13.jpg','1995','梅尔·吉布森','梅尔·吉布森 / 凯瑟琳·麦克马克 / 苏菲·玛索','威廉·华莱士童年时，其父、苏格兰民族英雄马索·华莱士在与英军的斗争中牺牲，他开始接受父亲好友的指导，学习苏格兰文化和武术。青年华莱士（梅尔·吉布森 饰）学成回到故乡，向美丽的少女梅伦求婚，不想梅伦被英军抢去且遭杀害。在广大村民“英雄之后”…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (403,'在这世界的角落',9,'zz14.jpg','2016','片渊须直','能年玲奈 / 细谷佳正 / 稲葉菜月','小铃（能年玲奈 配音）是一个整日里慢慢腾腾迷迷糊糊的姑娘，最大的爱好就是画画。眼看着到了嫁人的年纪，在父母的安排下，小铃来到了吴市，嫁给了名为北条周作（细谷佳正 配音）的男子，成为了北条家的媳妇。INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (404,'大逃亡',9,'zz15.jpg','1963','约翰·斯特奇斯','史蒂夫·麦奎因 / 詹姆斯·加纳 / 理查德·阿滕伯勒','这部史上最激动人心的冒险故事之一，以动作史诗的规格再现了二战期间一次真实的越狱行动——250名战俘试图通过地道从德国战俘营挣脱枷锁，影片详实刻画了行动的筹划、执行与后续波澜。史蒂夫·麦奎因凭借片中摩托车特技狂人的角色奠定其巨星地位，他与查…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (405,'阿尔及尔之战',9,'zz16.jpg','1966','吉洛·彭泰科沃','Brahim Hadjadj / Jean Martin / Saadi Yacef','吉洛·蓬泰科尔沃执导，是影史最具影响力的政治电影之一，生动再现了二十世纪五十年代阿尔及利亚脱离法国殖民统治的独立斗争中一个关键年份的动荡景象。随着双方暴力冲突不断升级，儿童在近距离射杀士兵，女性在咖啡馆安置炸弹，法国士兵则以酷刑手段试图瓦…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (406,'触碰的双手',9,'zz17.jpg','2018','Amma Asante','阿曼德拉·斯坦伯格 / 乔治·麦凯 / 艾比·考尼什','1944年的德國正值世界大戰，少女蕾娜的母親是德國人、父親是非裔，她因為膚色飽受壓迫；然而，她和希特勒的青年軍魯茲情不自禁地墜入愛河，為此兩人更陷入險地...',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (407,'帝国的毁灭',9,'zz18.jpg','2004','奥利弗·希施比格尔','布鲁诺·甘茨 / 亚历山德拉·玛丽亚·拉娜 / 科琳娜·哈福什','1945年4月，第二次世界大战接近尾声，苏联红军攻入柏林，第三帝国已濒临覆灭。希特勒与爱娃·布劳恩以及一众军政高层躲进柏林地下掩体，仍试图在不断恶化的战局中作出最后的挣扎。随着德军防线接连崩溃、命令无法执行，地堡中的希望逐渐被绝望取代，而…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (408,'大幻影',9,'zz19.jpg','1937','让·雷诺阿','Jean Gabin / 蒂塔·保洛 / Pierre Fresnay','三名法国飞行员在一次任务执行中被德军击落，波迪奥、迈克和罗森塔尔三人被带到战俘集中营。波迪奥与德军监狱长罗芬斯坦都是贵族出身，有着共同的政治见解，二人在狱中成为朋友。三人随后发现狱友正进行越狱计划，他们挖出一条逃跑的通道。迈克和罗森塔尔也…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (409,'养家之人',9,'zz20.jpg','2017','Nora Twomey','Saara Chaudry / Soma Bhatia / Noorin Gulamgaus','故事的主人公是一个阿富汗女孩Parvana，她们一家生活在塔利班的严酷统治之下，Parvana的爸爸被迫害入狱，为了养家糊口，她只能伪装成男孩打工挣钱。同时该片还将展现阿富汗地区的文化、历史以及风景名胜。',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (410,'奇幻核子战',9,'zz21.jpg','1964','西德尼·吕美特','亨利·方达 / 沃尔特·马修 / 弗里茨·韦弗','改编自尤金．贝狄克和哈维．威尔勒的作品，是一部从美苏对峙的冷战形势引伸出来的“写实幻想片"。内容讲述由于机械失误的关系，美国轰炸机队出发轰炸莫斯科，美国总统在无法唤回轰炸机之余，下令美军也将纽约摧毁。本片片中所描述的情况很有可能发生，因此…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (411,'你逃我也逃',9,'zz22.jpg','1942','恩斯特·刘别谦','卡罗尔·隆巴德 / 杰克·本尼 / 罗伯特·斯塔克','这部恩斯特·刘别谦的神经喜剧杰作，在令人捧腹的同时亦充满大胆锐气。杰克·本尼与卡洛·朗白（后者息影前最后作品）饰演纳粹占领区华沙的一对演员夫妇，二人意外卷入一场危险的间谍阴谋。本片是一部极具黑色幽默胆魄的好莱坞电影，于美国加入二战前夕投入…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (412,'伊万的童年',9,'zz23.jpg','1962','安德烈·塔可夫斯基','尼古拉·彼得洛维奇·布尔利亚耶夫 / Валентин Зубков / Евгений Жариков','残酷的战争摧毁了12岁男孩伊万的童年，母亲和姐姐早年被德国军队杀害。怀着对纳粹的仇恨，他加入了苏联红军，小小年纪的伊万当上了一名小侦察员，深入德军敌后，执行危险的任务，在战火和死亡中穿梭。由于年龄的关系，中尉戈克森甚至不敢相信伊万的身份，…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (413,'烽火母女泪',9,'zz24.jpg','1960','维托里奥·德西卡','索菲亚·罗兰 / 艾伦诺拉·布朗 / 让-保罗·贝尔蒙多','该片讲述了二战期间，一家小杂货店的寡妇为了躲避战争，带着女儿一起逃往家乡的故事。',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (414,'穿条纹睡衣的男孩',9,'zz25.jpg','2008','马克·赫尔曼','阿萨·巴特菲尔德 / 维拉·法梅加 / 大卫·休里斯','八岁的布鲁诺随身为纳粹军官的父亲从柏林搬到乡下。离开熟悉的朋友后，孤独的布鲁诺很快注意到新家附近一片被铁丝网围住的地方，那里的人终日穿着相似的“条纹睡衣”，这让他充满好奇。一次偷偷探索中，布鲁诺结识了铁丝网另一边的同龄男孩施穆尔，并时常带…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (415,'桂河大桥',9,'zz26.jpg','1957','大卫·里恩','威廉·霍尔顿 / 亚历克·吉尼斯 / 杰克·霍金斯','一位英国上校在与日本战俘营指挥官化解分歧后，竟协作督建部下为俘虏者建造一座铁路桥——而对盟军旨在炸毁该桥的计划全然不知。',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (416,'天上再见',9,'zz27.jpg','2017','Albert Dupontel','纳威尔·佩雷兹·毕斯卡亚特 / Albert Dupontel / 罗兰·拉斐特','改编自皮埃尔·勒梅特的同名小说。1919年，第一次世界大战的两名幸存者，天才画家爱德华和普通会计师阿尔贝，决定利用人们对战争纪念的热情，策划一场纪念碑骗局。在“疯狂年代”的法国，这场大胆的骗局逐渐变得危险而失控。',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (417,'影武者',9,'zz28.jpg','1980','黑泽明','仲代达矢 / 山崎努 / 萩原健一','一位军阀离世后，一名盗贼出身的农民被召来冒充他，随即发现自己不仅被军阀的亡灵纠缠，更被自身的野心所困。在黑泽明的这部晚期彩色杰作中，他回归武士电影题材，并再度探讨其创作生涯的核心主题——幻觉与现实之间的博弈。通过对封建时代日本辉煌图景与战…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (418,'一袋弹子',9,'zz29.jpg','2017','克里斯丁·杜瓦','Dorian Le Clech / Batyste Fleurial / 帕特里克·布鲁尔','影片改编自法国当代著名作家约瑟夫·若福的自传小说《弹子袋》。在被德军占领的法国，莫里斯和乔是一对年轻的犹太兄弟，父亲经营着一家理发店，一家人生活温馨又美满。直到纳粹要求所有犹太人必须在外衣上缝上一个黄色的六角星以示区别，由于当时人们对犹太…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (419,'地雷区',9,'zz30.jpg','2015','马丁·赞里维特','罗兰·默勒 / 路易斯·霍夫曼 / 米克尔·福尔斯加德','1945年5月德国纳粹投降之后，一群年轻的德军俘虏被交给丹麦当局，他们被送往西海岸。在那里他们必须用自己的双手来除雷。二战期间，德国人曾在这片海岸布置了超过200万枚的地雷。这群男孩们在丹麦军官卡尔·莱奥博德·拉斯穆森（罗 兰德·莫尔 饰…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (420,'我眼中的阴影',9,'zz31.jpg','2021','奥勒·博内代尔','Bertram Bisgaard Enevoldsen / Ester Birch / Ella Nilsson','第二次世界大战.1945年3月21日，英国皇家空军开始执行轰炸哥本哈根盖世太保总部的任务。这次袭击造成了致命的后果，因为一些轰炸机意外袭击了一所学校，造成120多人丧生，其中86人是儿童。几名哥本哈根居民的命运因此交织在了一起。本片改编自…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (421,'他们已不再变老',9,'zz32.jpg','2018','彼得·杰克逊','Thomas Adlam / William Argent / John Ashby','彼得·杰克逊运用最先进的技术修复了百年以上的原始档案影像，让那些最能讲述这段历史的人——亲历者——重现于世。出于对第一次世界大战的个人兴趣，杰克逊决心还原士兵们的日常生活。在 BBC 和帝国战争博物馆的档案馆中潜心研究数月后，杰克逊逐渐构…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (422,'潘神的迷宫',9,'zz33.jpg','2006','吉尔莫·德尔·托罗','伊万娜·巴克罗 / 塞尔希·洛佩斯 / 玛丽贝尔·韦尔杜','这部荣获奥斯卡奖的黑暗童话，以西班牙内战结束五年后为背景，浓缩了吉列尔莫·德尔托罗视觉风格浓烈、突破类型桎梏的独特匠心。十一岁的奥菲莉亚（伊万娜·巴克罗饰，表演兼具成熟韵味与纯真质感）随怀孕的母亲迁往乡间，被迫直面法西斯统治的恐怖——她的…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (423,'西线无战事',9,'zz34.jpg','1930','Lewis Milestone','Louis Wolheim / Lew Ayres / John Wray','第一次世界大战期间，德国政府以漂亮的口号呼吁年轻热情的学生志愿者投身战场保家卫国。一腔热血的德国青年保罗·鲍曼怀着英雄理想投身到一战之中。然而当保罗和他的同学们经过训练后，被派往西线参战时，他们目睹到的却是残酷的饥饿、血腥和死亡。战争的荒…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (424,'野战排',9,'zz35.jpg','1986','奥利弗·斯通','查理·辛 / 威廉·达福 / 汤姆·贝伦杰','一名年轻士兵在越南战场上直面战争的恐怖与人性的双重性，陷入道德危机。',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (425,'黄金时代',9,'zz36.jpg','1946','威廉·惠勒','达纳·安德鲁斯 / Fredric March / Harold Russell','三位二战老兵回到美国小镇的家中，发现他们与家人的生活早已不复往昔。',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (426,'解放黑奴',9,'zz37.jpg','2022','安东尼·福奎阿','威尔·史密斯 / 本·福斯特 / 凯特琳·伯利','威尔·史密斯饰演真实历史人物：饱受折磨后逃出美国南方奴隶主奴役的黑人彼得、美国奴隶制的著名“证据”照片的主人公。INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (427,'狙击手·白乌鸦',9,'zz38.jpg','2022','Marian Bushan','Павло Алдошин / 玛丽娜·科什金娜 / Андрій Мостренко','Mykola 是一个古怪的和平主义者，他希望对人类有用。 当战争在顿巴斯打响时，武装分子杀死了他怀孕的妻子并将他的家烧成平地，米科拉的天真世界正在崩溃。 康复后，他做出了重大决定，并被招募到了一家狙击连。 遇到杀害妻子的凶手后，他情绪崩溃…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (428,'卢旺达饭店',9,'zz39.jpg','2004','特里·乔治','唐·钱德尔 / 索菲·奥科内多 / 尼克·诺尔蒂','影片来源于一个真实的故事。1962年，卢旺达宣布独立后，胡图族与图西族两部族之间矛盾重重，多次发生冲突，战事持续不断。 1994年4月6日，一架载着卢旺达胡图族总统朱韦纳尔·哈比亚利马纳和布隆迪总统西普里安·恩塔里亚米拉的座机在卢旺达首都…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (429,'盟约',9,'zz40.jpg','2023','盖·里奇','杰克·吉伦哈尔 / 达尔·萨利姆 / 肖恩·萨加尔','美军中士约翰·金利（杰克·吉伦哈尔 饰）最后一次在阿富汗执行任务，和当地翻译艾哈迈德一起调查该地区。他们的部队在巡逻中遭到伏击，两人成为唯一的幸存者，在敌人的追击下，艾哈迈德冒着生命危险带着受伤的金利穿过数英里的岖崎地形到达安全地带。回到…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (430,'诺曼底72小时',9,'zz41.jpg','2026','安东尼·马拉斯','安德鲁·斯科特 / 布兰登·费舍 / 凯瑞·康顿','1944年，诺曼底登陆进入最后72小时，盟军大规模登陆部队已经集结完毕，一切准备就绪，唯独难以预测的天气成为决定行动成败的关键。气象学家詹姆斯·斯塔格上校根据自己的判断预警风暴即将来临，但推迟行动同样可能导致盟军部署暴露。面对来自盟军高层…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (431,'地下',9,'zz42.jpg','1995','埃米尔·库斯图里卡','Мики Манојловић / 拉扎尔·里斯托夫斯基 / Mirjana Joković','1941年的南斯拉夫正处于德国法西斯占领时期。一夜，马高为庆祝好友黑仔加入共产党，请来了小乐队助兴。他和黑仔两人喝着白兰地，驾着马车驶过空旷的街道，甚至鸣枪欢呼。黑仔被唠叨的妻子劫回了家，马高则去找妓女鬼混。马高的弟弟伊万是动物园的管理员…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (432,'战地军魂',9,'zz43.jpg','1953','比利·怀尔德','威廉·霍尔顿 / Don Taylor / 奥托·路德维希·普雷明格','二战时期，一批美国战俘被关押在德军的监狱里，故事就发生在17号监狱（Stalag 17）。有两名囚犯想要越狱，却被德军所杀，监狱里的囚犯们开始怀疑他们其中有人出卖了他们。大家都把嫌疑集中在一个人身上——狡猾的Sefton（威廉·霍尔登 W…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (433,'和巴什尔跳华尔兹',9,'zz44.jpg','2008','Ari Folman','Ari Folman / Mickey Leon / Ori Sivan','酒吧里的一夜，老友向导演阿里吐露反复出现的噩梦：总被26条恶犬追赶。夜夜如此，犬数不变。两人推断这与八十年代初的第一次黎巴嫩战争中以军任务有关。阿里惊觉自己对那段岁月竟毫无记忆。受此谜团牵引，他动身寻访散居世界各地的战友与故人，试图揭开往…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (434,'金橘',9,'zz45.jpg','2013','ზაზა ურუშაძე','Lembit Ulfsak / გიორგი ნაკაშიძე / Elmo Nüganen','1990年的阿布哈兹战争期间，爱沙尼亚人伊福被迫留下了收获金橘，流血冲突打到了他家门口，一个受伤的男人留了下来，伊福被迫之下收留了他。',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (435,'阿伊达，你往何处去？',9,'zz46.jpg','2021','Jasmila Žbanić','Jasna Đuričić / Izudin Bajrović / Boris Ler','波斯尼亚，1995年7月11日。艾达是联合国在斯雷布雷尼察小镇的翻译。当塞尔维亚军队占领该镇时，她的家人与成千上万的民众一同在联合国营地寻求庇护。作为谈判的知情者，艾达接触到她需要解读的关键信息。她的家人和同胞面临的前景是拯救还是死亡？她…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (436,'最后的武士',9,'zz47.jpg','2003','爱德华·兹威克','汤姆·克鲁斯 / 渡边谦 / 蒂莫西·斯波','1865年，美国内战结束。但战士的心却无法安宁，在随即而来的大规模西进运动中，刚刚从内战硝烟中幸存下来的白人士兵，又被带到了击杀印第安人的第一线。 上尉纳森.欧格仁在战争中见证了过多的鲜血与暴力，以至于迷失了自己的灵魂；特别是看到上级军官…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (437,'最长的一天',9,'zz48.jpg','1962','Ken Annakin / Andrew Marton / Bernhard Wicki','约翰·韦恩 / 罗伯特·米彻姆 / 亨利·方达','影片描绘的是登陆诺曼底的第一天所发生的事件，所谓最长的一天是该片分别从盟军和德军双方面的角度同时描述诺曼第登陆这一历史战役的来龙去脉，以及双方在此期间的重要反应，手法平实，场面逼真，让整个事件在观众眼前重现。并且粗中有细，无论是决策的将军…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (438,'波斯语课',9,'zz49.jpg','2020','瓦迪姆·佩雷尔曼','纳威尔·佩雷兹·毕斯卡亚特 / 拉斯·艾丁格 / 约纳斯·奈伊','二战期间，犹太人吉尔斯在集中营谎称自己是波斯人保命，被一位德国军官看中要求教自己波斯语。对波斯语完全不懂的小卷只能凭空编出一门语言，他开始用集中营中关押的犹太人的名字作为词根，编造出上千个“波斯语”单词。军官在残暴的环境中对小卷竟有了依赖…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (439,'地中海',9,'zz50.jpg','1991','Gabriele Salvatores','Diego Abatantuono / Claudio Bigagli / Giuseppe Cederna','二战后期，在地中海的某个小岛，某舰艇上有一群意大利守卫负责守卫这个军事重地。然而，这群被战争遗忘的士兵无意中闯入了一座小镇，他们发现那里的居民并没有被战争侵袭，依旧过着无忧无虑的生活。起初，这几个士兵总是提心吊胆，生怕有外敌入侵，因为误会…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (440,'第七封印',10,'qh1.jpg','1957','英格玛·伯格曼','甘纳尔·布耶恩施特兰德 / 本特·埃克罗特 / 尼尔斯·波普','十字军东征归来的骑士精疲力竭，发现中世纪瑞典正被瘟疫笼罩。当披着斗篷的死神突然现身时，骑士向他发起了象棋对决的挑战。随着这场命运棋局的推进，骑士与随从在绝望的社会中邂逅了形形色色的边缘人。导演英格玛·伯格曼以此展开对信仰本质与死亡折磨的深…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (441,'哈利·波特与死亡圣器（下）',10,'qh2.jpg','2011','大卫·叶茨','丹尼尔·雷德克里夫 / 艾玛·沃森 / 鲁伯特·格林特','哈利、罗恩和赫敏继续寻找并摧毁伏地魔剩余的魂器，而新的线索最终将他们再次带回已经被食死徒控制的霍格沃茨。随着哈利归来，麦格教授、纳威以及学校的师生和反抗力量开始集结，准备守卫霍格沃茨；伏地魔则率领食死徒大军向学校逼近，一场决定魔法世界命运…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (442,'扎克·施奈德版正义联盟',10,'qh3.jpg','2021','扎克·施奈德','本·阿弗莱克 / 亨利·卡维尔 / 盖尔·加朵','为了确保超人没有白白牺牲，蝙蝠侠和神奇女侠计划招募一支超人类团队来保护世界。这项任务比布鲁斯的设想要困难得多，因为每个新人都必须面对并跨越自己过去的心魔，团结起来，最终形成前所未有的联盟，否则就无法阻止从荒原狼、狄萨德和达克赛德毁灭地球。',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (443,'与神同行：罪与罚',10,'qh4.jpg','2017','金容华','河正宇 / 车太贤 / 朱智勋','阴间有法，所有亡者在死后的49天内都要经过七次审判——分别在杀人狱、懒惰狱、欺骗狱、不义狱、背叛狱、暴力狱、天伦狱中进行，只有通过了七次审判宣告无罪的亡者，才有获得新生的机会。消防员金子洪在一场火灾当中为了救一名女孩而不幸牺牲。地狱使者解…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (444,'与神同行2：因与缘',10,'qh5.jpg','2018','金容华','河正宇 / 朱智勋 / 金香起','三位阴间使者江林（河正宇 饰）、解怨脉（朱智勋 饰）、德春（金香起 饰）即将带领第49位「贵人」金秀鸿（金东旭 饰）进行地狱审判，他们同时发现人间有一位家神（马东锡 饰），试图把早该阳寿已尽的老人强留人间。阴间使者为了带走该名老人，开始与…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (445,'奥德赛',10,'qh6.jpg','2026','克里斯托弗·诺兰','马特·达蒙 / 汤姆·赫兰德 / 安妮·海瑟薇','改编自荷马史诗《奥德赛》。特洛伊战争结束后，伊萨卡国王奥德修斯历经艰险、踏上漫长归乡之旅。',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (446,'新·驯龙高手',10,'qh7.jpg','2025','迪恩·德布洛斯','梅森·泰晤士 / 妮可·帕克 / 杰拉德·巴特勒','在险峻的博克岛上，维京人与龙族世代为敌，猎杀巨龙也被视作成为真正勇士的证明。身为族长史图依克的儿子，小嗝嗝却瘦弱又不善战斗，始终无法得到父亲和族人的认可。一次龙群袭击中，他意外击落了传说中最危险的夜煞，却在面对受伤的没牙仔时选择放下武器。…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (447,'奇迹少女 龙女觉醒',10,'qh8.jpg','2021','托马斯·阿斯特鲁克','Anouck Hautbois / 吉纳维芙·杜昂 / Benjamin Bollen','在得知艾俊去上海后，马丽娜借着给舅公送生日礼物的机会也来到了上海。可刚到上海，马丽娜的手机、米可幻奇以及精灵宝奇都被偷走了！束手无策的她接受了一个名叫飞儿的女孩的帮助，殊不知就是飞儿偷走了她的东西。她们一起对抗贪财的钞票张，愤怒的他被黑魔…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (448,'怪物之子',10,'qh9.jpg','2015','细田守','役所广司 / 宫崎葵 / 染谷将太','《怪物之子》的世界里，在人类世界之外还有一个怪物生活的世界。而两者之间的交界处则是人间界的涉谷所在以及在怪物界名为“涉天街”的地方。故事讲述了某一日，孤身一人的少年误入怪物世界的少年遇到了同样孤身一人的怪物，两者相遇后开展的超出想象的冒险…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (449,'泯灭天使',10,'qh10.jpg','1962','路易斯·布努埃尔','Silvia Pinal / Jacqueline Andere / 克劳迪奥·布鲁克','本片是布努艾尔与墨西哥女演员希尔维亚·比那尔（Silvia Pinal）合作，由比那尔的丈夫古斯塔沃·阿拉特里斯特（Gustavo Alatriste）出资制片的三部曲中的第二部。故事从一场盛大的晚宴开始。诺比尔夫妇在家款待朋友，可正当客…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (450,'铃芽之旅',10,'qh11.jpg','2022','新海诚','原菜乃华 / 松村北斗 / 深津绘里','生活在日本九州田舍的17岁少女·铃芽遇见了为了寻找“门”而踏上旅途的青年。追随着青年的脚步，铃芽来到了山上一片废墟之地，在这里静静伫立着一扇古老的门，仿佛是坍塌中存留的唯一遗迹。铃芽仿佛被什么吸引了一般，将手伸向了那扇门……不久之后，日本…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (451,'我的英雄学院：两位英雄',10,'qh12.jpg','2018','长崎健司','山下大辉 / 三宅健太 / 志田未来','白炽的期末考试结束，暑假的林间集训等候了的英雄高中成员。德克和奥尔迈特受到某个人的邀请，我造访了漂浮在海外的巨大人口移动都市“I・爱岛”。全世界的科学研究者们的智慧汇集了的确实象科学好莱坞一样的岛展示了个性和英雄项目的研究成果的正在召开中…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (452,'驯龙高手',10,'qh13.jpg','2010','迪恩·德布洛斯 / 克里斯·桑德斯','杰伊·巴鲁切尔 / 杰拉德·巴特勒 / 克雷格·弗格森','维京岛国的少年小嗝嗝（杰伊•巴鲁切尔 Jay Baruchel 配音）是部落统领伟大的斯托里克（杰拉德·巴特勒 Gerard Butler 配音）的儿子，他非常想像自己的父亲一样亲手屠龙——这些飞龙是岛上维京人放牧羊群的主要天敌——但他每…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (453,'怪兽电力公司',10,'qh14.jpg','2001','皮特·多克特','约翰·古德曼 / 比利·克里斯托 / 玛丽·吉布斯','我们不知道，在那样的世界里住着那样一群怪物。他们长相滑稽，却必须装作狰狞。因为，在夜深的时候，他们要悄悄的出现在孩子的衣橱里，吓唬刚刚甜美睡去的宝宝。一切，只因为他们是怪物电力公司的员工，而孩子的尖叫，则是怪物王国发电的全部能量。怪物们害…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (454,'圣诞夜惊魂',10,'qh15.jpg','1993','亨利·塞利克','丹尼·艾夫曼 / 克里斯·萨兰登 / 凯瑟琳·欧哈拉','圣诞节能否得救？厌倦了千篇一律的惊吓套路，万圣节镇的南瓜王杰克·斯凯灵顿渴望传播圣诞的快乐。然而他善意的行动却将圣诞老人置于险境，给天下好孩子们带来了一场噩梦。[迪士尼]',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (455,'美食总动员',10,'qh16.jpg','2007','布拉德·伯德','帕顿·奥斯瓦尔特 / 卢·罗曼诺 / 伊恩·霍姆','尽管雷米拥有惊人的嗅觉和敏锐的味觉，但他成为厨师的梦想似乎遥不可及，原因只有一个——他是一只老鼠！命运弄人，他竟然来到了他已故偶像奥古斯特·古斯托的世界著名餐厅。凭借着一点烹饪的勇气和垃圾工林奎尼的帮助，雷米烹制出美味佳肴，甚至连刻薄的厨…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (456,'少年魔法师特别版：双面艾莉斯',10,'qh17.jpg','2013','Victor Gonzalez','赛琳娜·戈麦斯 / Jake T. Austin / 珍妮佛·史東','鲁索一家去意大利探亲戚，艾利克斯试图证明她不仅仅是⼀个看似无忧无虑的年轻魔法师，却无意中念了一个咒语，创造了⼀个善良的自己和⼀个邪恶的自己。',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (457,'文森特',10,'qh18.jpg','1982','蒂姆·伯顿','文森特·普莱斯','年仅七岁的文森特，他总是表现出很有教养，并且做大人让他做的事。但他又是一个爱幻想的男孩，他的脑子里充满了各式各样的古怪而新奇的念头，却受到成人社会的压抑 ，他陷入到深深的孤独之中，活在冥想中那充满鬼怪的世界里。文森特最喜欢的作家是爱伦坡（…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (458,'魔女宅急便',10,'qh19.jpg','1989','宫崎骏','高山南 / 佐久间丽 / 山口胜平','琪琪今年13岁了，按照魔法界的规矩，魔法少女年满13岁就要出外进行为期一年的修行。所以琪琪带着宠物黑猫吉吉踏上了修行之旅。然而，修行之旅开识得并不顺利，当琪琪来到海边一座大城市时，人们并没有欢迎她的到来，人人都不搭理她。幸亏琪琪有一颗善良…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (459,'加勒比海盗1：黑珍珠号的诅咒',10,'qh20.jpg','2003','戈尔·维宾斯基','约翰尼·德普 / 杰弗里·拉什 / 奥兰多·布鲁姆','故事发生在17世纪，传说中海盗最为活跃的加勒比海。风趣迷人的杰克·斯伯洛，是活跃在加勒比海上的海盗，拥有属于自己的“黑珍珠”号海盗船。对他来说，最惬意的生活就是驾驶着“黑珍珠”号在加勒比海上游荡，自由自在的打劫过往船只。但不幸的是，他的仇…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (460,'哈利·波特与火焰杯',10,'qh21.jpg','2005','迈克·内威尔','丹尼尔·雷德克里夫 / 鲁伯特·格林特 / 艾玛·沃森','哈利迎来了在霍格沃茨的第四个学年，这一年学校将举办久负盛名而又危险重重的“三强争霸赛”，来自布斯巴顿和德姆斯特朗两所魔法学校的学生也来到霍格沃茨参加竞争。按照规定，只有年满17岁的学生才有资格报名，然而负责选出勇士的“火焰杯”却意外吐出了…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (461,'巨蟒与圣杯',10,'qh22.jpg','1975','特里·琼斯 / 特里·吉列姆','格雷厄姆·查普曼 / 约翰·克里斯 / 埃里克·艾德尔','故事跟随亚瑟王和他的圆桌骑士展开寻找圣杯的征程。这绝非寻常的中世纪骑士与战马传说——首先，由于王国资源短缺，所有战马竟都被用拍击椰子壳模仿马蹄声的仆人所替代！',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (462,'月神',10,'qh23.jpg','2012','埃里康·卡萨罗萨','Tony Fucile / Krista Sheffler / Phil Sheridan','皮克斯动画工作室出品，获第84届奥斯卡最佳动画短片提名，短短7分钟，没有对白，一个关于祖孙三代、关于成长的奇幻故事：INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (463,'红猪',10,'qh24.jpg','1992','宫崎骏','森山周一郎 / 加藤登纪子 / 桂三枝','20世纪20年代末的亚得里亚海，一战时期的王牌飞行员波鲁克不知何故变成了猪的模样。战争结束后，他驾驶着红色水上飞机成为赏金猎人，专门追捕在海上作恶的空中劫匪，也因此被人称为“红猪”。不甘心屡屡受挫的劫匪们请来美国飞行员卡地士对付波鲁克，一…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (464,'寻龙传说',10,'qh25.jpg','2021','卡洛斯·洛佩斯·埃斯特拉达 / 唐·霍尔','凯莉·玛丽·陈 / 奥卡菲娜 / 嘉玛·陈','很久以前，在充满奇幻色彩的龙佑之邦，人类和龙和谐地生活在一起。但当一股邪恶的力量袭来，龙牺牲了自己来拯救人类。500年后，同样的邪恶力量卷土重来，只有一个孤独的战士拉雅承担重任，追踪传说中的最后一条龙，以修复这块破碎的土地，团结分裂的人民…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (465,'海贼王：狂热行动',10,'qh26.jpg','2019','大冢隆史','田中真弓 / 中井和哉 / 冈村明美','“海贼王系列”第14部剧场版，也是《海贼王》动画二十周年纪念之作。 以超新星为代表的众多航海家纷纷现身世界最大的航海家庆典——航海世博会。草帽海贼团也收到了主办者费斯塔的邀请函，搭乘万里阳光号前往。原以为海贼们的狂热世博会只是为争夺“海贼…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (466,'怪物史瑞克',10,'qh27.jpg','2001','安德鲁·亚当森 / 维基·詹森','麦克·梅尔斯 / 艾迪·墨菲 / 卡梅隆·迪亚兹','从前，在一片遥远的沼泽里，住着一个脾气暴躁的怪物史莱克（迈克·迈尔斯 配音）。他珍贵的独居生活，突然被一群恼人的童话人物入侵而彻底打乱。[梦工厂]',8,0);
