INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (468,'兽兵卫忍风帖',10,'qh29.jpg','1993','川尻善昭','山寺宏一 / 筱原惠美 / 青野武','在一个风雨交加的晚上，一伙神秘的人策马狂奔向下田村的方向，之后这个村子就爆发了一场瘟疫，所有的村民都死了。在望月番番主的首肯下，甲贺组众忍者前往该村调查，不料路上遇到一个刀枪不如的彪形大汉的袭击，只有忍女炎阳（筱原惠美 配音）在一个男子的…',8,0);
INSERT INTO films (cid,title,tid,cover,year,author,present,describes,rating,commentscount) VALUES (469,'真人快打2',10,'qh30.jpg','2026','西蒙·麦奎德','卡尔·厄本 / 阿德莱恩·鲁道夫 / 林路迪','过气好莱坞演员强尼·凯奇（卡尔·厄本 饰）被意外选中，加入一场决定地球命运的真人快打。吉塔娜（阿德莱恩·鲁道夫 饰）、刀锋索尼娅（杰西卡·麦克娜美 饰）、卡诺（约什·劳森 饰）、刘康（林路迪 饰）、贾克斯（麦卡德·布鲁克斯 饰）、尚宗（黄…',8,0);
