-- 「红影赏析」数据库初始化脚本（redfilmdbs）
-- 用法：mysql -u root -p < redfilmdbs.sql
-- 由 redfilmdbs.db 导出，含 10 个电影类型 + 550 部电影

CREATE DATABASE IF NOT EXISTS redfilmdbs DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci;
USE redfilmdbs;

DROP TABLE IF EXISTS discussjudges;
DROP TABLE IF EXISTS filmjudges;
DROP TABLE IF EXISTS discuss;
DROP TABLE IF EXISTS films;
DROP TABLE IF EXISTS filmtype;
DROP TABLE IF EXISTS users;

CREATE TABLE users (
  uid int NOT NULL AUTO_INCREMENT,
  uname varchar(100) NOT NULL,
  upwd varchar(255) NOT NULL,
  nickname varchar(100) DEFAULT NULL,
  avatar varchar(200) DEFAULT NULL,
  sex varchar(50) DEFAULT NULL,
  phone varchar(50) DEFAULT NULL,
  remark varchar(200) DEFAULT NULL,
  PRIMARY KEY (uid), UNIQUE KEY uk_uname (uname)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT="用户表";

CREATE TABLE filmtype (
  tid int NOT NULL,
  name varchar(100) NOT NULL,
  cover varchar(200) DEFAULT NULL,
  remark varchar(500) DEFAULT NULL,
  PRIMARY KEY (tid)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT="电影类型表";

CREATE TABLE films (
  cid int NOT NULL AUTO_INCREMENT,
  title varchar(200) NOT NULL,
  tid int NOT NULL,
  cover varchar(200) DEFAULT NULL,
  year varchar(50) DEFAULT NULL,
  author varchar(200) DEFAULT NULL,
  present varchar(100) DEFAULT NULL,
  describes text,
  rating int DEFAULT NULL,
  commentscount int DEFAULT 0,
  PRIMARY KEY (cid), KEY idx_films_tid (tid)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT="电影表";

CREATE TABLE filmjudges (
  cjid int NOT NULL AUTO_INCREMENT,
  cid int NOT NULL,
  uid int NOT NULL,
  rating int DEFAULT NULL,
  jdate datetime DEFAULT NULL,
  PRIMARY KEY (cjid)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT="电影评分表";

CREATE TABLE discuss (
  did int NOT NULL AUTO_INCREMENT,
  uid int NOT NULL,
  cid int NOT NULL,
  comment text,
  cdate datetime DEFAULT NULL,
  topcount int DEFAULT 0,
  lowcount int DEFAULT 0,
  PRIMARY KEY (did), KEY idx_discuss_cid (cid)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT="影评表";

CREATE TABLE discussjudges (
  djid int NOT NULL AUTO_INCREMENT,
  did int NOT NULL,
  uid int NOT NULL,
  toplow int DEFAULT NULL,
  jdate datetime DEFAULT NULL,
  PRIMARY KEY (djid)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT="影评点赞表";

